using System.Diagnostics;
using System.Text.Json;
using StarSyncUniverse.Domain;
using StarSyncUniverse.Localization;
using StarSyncUniverse.Services;

namespace StarSyncUniverse.Renderer;

/// <summary>
/// Generates the local WebView2 universe-map document from an immutable renderer payload.
///
/// Design boundaries:
/// - game/source values are serialized as native data and are never localized or rewritten here;
/// - application UI wording comes from <see cref="UiLocalizationCatalog"/>;
/// - every game/user/external value inserted through innerHTML must be HTML-escaped;
/// - privileged I/O stays in the WPF host/services and is requested through the WebView bridge;
/// - direct renderer network access is disabled by the generated Content Security Policy.
///
/// The HTML/CSS/JavaScript currently remain co-located because they form one tightly coupled render
/// artifact. See docs/ARCHITECTURE.md for the extraction boundary planned for future refactoring.
/// </summary>
public static class MapHtmlRenderer
{
    private static string GetStarBreakerVersion(string? path)
    {
        if (string.IsNullOrWhiteSpace(path) || !File.Exists(path)) return "NOT FOUND";
        try
        {
            var info = FileVersionInfo.GetVersionInfo(path);
            return !string.IsNullOrWhiteSpace(info.ProductVersion) ? info.ProductVersion! :
                !string.IsNullOrWhiteSpace(info.FileVersion) ? info.FileVersion! : "DETECTED";
        }
        catch { return "DETECTED"; }
    }

    private static bool IsPlaceholderGameText(string? value)
    {
        if (string.IsNullOrWhiteSpace(value)) return true;
        return value.Contains("UNINITIALIZED", StringComparison.OrdinalIgnoreCase);
    }

    private static string GetScUnpackedVersion(string? root)
    {
        if (string.IsNullOrWhiteSpace(root) || !Directory.Exists(root)) return "NOT FOUND";
        try
        {
            foreach (var name in new[] { "version.txt", "VERSION", "build.txt" })
            {
                var versionPath = Path.Combine(root, name);
                if (!File.Exists(versionPath)) continue;
                var text = File.ReadAllText(versionPath).Trim();
                if (!string.IsNullOrWhiteSpace(text)) return text;
            }
            var positions = Path.Combine(root, "starmap_positions.json");
            var folder = Path.GetFileName(Path.TrimEndingDirectorySeparator(root));
            if (File.Exists(positions))
                return $"{folder} / snapshot {File.GetLastWriteTimeUtc(positions):yyyy-MM-dd}";
            return folder;
        }
        catch { return "DETECTED"; }
    }

    public static string Build(
        UniverseDataset dataset,
        IReadOnlyDictionary<string, UniverseDataset>? allDatasets = null,
        NavigationTarget? initialNavigationStart = null,
        NavigationTarget? initialNavigationDestination = null,
        IReadOnlyList<BookmarkRecord>? bookmarks = null,
        IReadOnlyList<BookmarkGroupRecord>? bookmarkGroups = null,
        IReadOnlyList<LocationUserOverrideRecord>? locationOverrides = null,
        IReadOnlyDictionary<string, LiveSurfaceTextureAsset>? liveSurfaceTextures = null,
        IReadOnlyList<JumpConnection>? jumpConnections = null,
        ScUnpackedKnowledgeDatabase? knowledgeDatabase = null,
        StarSyncUniverseSettings? applicationSettings = null,
        MapDisplaySettings? displaySettings = null)
    {
        allDatasets ??= new Dictionary<string, UniverseDataset>(StringComparer.OrdinalIgnoreCase)
        {
            [dataset.System] = dataset
        };
        bookmarks ??= [];
        bookmarkGroups ??= [];
        locationOverrides ??= [];
        liveSurfaceTextures ??= new Dictionary<string, LiveSurfaceTextureAsset>(StringComparer.OrdinalIgnoreCase);
        jumpConnections ??= [];
        applicationSettings ??= StarSyncUniverseSettings.Default;
        displaySettings ??= MapDisplaySettings.Default;
        var galaxySchematic = GalaxySchematicBuilder.Build(allDatasets, jumpConnections);
        var systemOverview = SystemOverviewCatalog.LoadForSystem(dataset.System);
        var surfaceTargets = SurfaceTargetCatalogBuilder.Build(dataset);
        var syncHostIdentity = new UniverseSyncHostClientIdentityService().GetOrCreate();

        var entityKnowledge = new Dictionary<string, ScKnowledgeMatch>(StringComparer.OrdinalIgnoreCase);
        var surfaceKnowledge = new Dictionary<string, ScKnowledgeMatch>(StringComparer.OrdinalIgnoreCase);
        IReadOnlyList<ScKnowledgeLocation> knowledgeLocations = [];
        ScKnowledgeSummary? knowledgeSummary = null;
        if (knowledgeDatabase is not null)
        {
            knowledgeSummary = knowledgeDatabase.Summary;
            knowledgeLocations = knowledgeDatabase.LocationsForSystem(dataset.System);
            foreach (var entity in dataset.Entities)
            {
                var match = knowledgeDatabase.MatchLocation(entity.SourceUuid, entity.Name, dataset.System, entity.ParentSourceUuid, entity.SourcePath);
                if (match is not null) entityKnowledge[entity.Id] = match;
            }
            foreach (var target in surfaceTargets)
            {
                var directMatch = knowledgeDatabase.MatchLocation(target.SourceUuid, target.Name, dataset.System, null, target.SourcePath);
                var positionMatch = directMatch is null || IsPlaceholderGameText(directMatch.Location.Name)
                    ? knowledgeDatabase.MatchSurfaceLocationByPosition(
                        dataset.System,
                        target.BodyName,
                        target.BodyLocalX,
                        target.BodyLocalY,
                        target.BodyLocalZ)
                    : null;
                var match = positionMatch is not null && !IsPlaceholderGameText(positionMatch.Location.Name)
                    ? positionMatch
                    : directMatch ?? positionMatch;
                if (match is not null) surfaceKnowledge[target.AnchorId] = match;
            }
            knowledgeLocations = knowledgeLocations
                .Concat(entityKnowledge.Values.Select(x => x.Location))
                .Concat(surfaceKnowledge.Values.Select(x => x.Location))
                .Where(x => !string.IsNullOrWhiteSpace(x.Uuid))
                .GroupBy(x => x.Uuid, StringComparer.OrdinalIgnoreCase)
                .Select(g => g.First())
                .OrderBy(x => x.Name, StringComparer.OrdinalIgnoreCase)
                .ToArray();
        }

        var payload = JsonSerializer.Serialize(new
        {
            system = dataset.System,
            build = dataset.Build,
            primarySource = dataset.PrimarySource,
            secondarySource = dataset.SecondarySource,
            systemOverview,
            applicationSettings = new
            {
                localP4kUpdateAdapterEnabled = applicationSettings.LocalP4kUpdateAdapterEnabled,
                scUnpackedImportEnabled = applicationSettings.ScUnpackedImportEnabled,
                onlineLocationEnrichmentEnabled = applicationSettings.OnlineLocationEnrichmentEnabled,
                onlineLocationEnrichmentConsent = applicationSettings.OnlineLocationEnrichmentConsent,
                onlineLocationEnrichmentActive = applicationSettings.OnlineLocationEnrichmentActive,
                starBreakerPath = applicationSettings.StarBreakerPath ?? string.Empty,
                starBreakerDetected = !string.IsNullOrWhiteSpace(applicationSettings.StarBreakerPath) && File.Exists(applicationSettings.StarBreakerPath),
                starBreakerVersion = GetStarBreakerVersion(applicationSettings.StarBreakerPath),
                dataP4kPath = applicationSettings.DataP4kPath ?? string.Empty,
                scUnpackedRoot = applicationSettings.ScUnpackedRoot ?? string.Empty,
                scUnpackedDetected = !string.IsNullOrWhiteSpace(applicationSettings.ScUnpackedRoot) && Directory.Exists(applicationSettings.ScUnpackedRoot) && File.Exists(Path.Combine(applicationSettings.ScUnpackedRoot, "starmap_positions.json")),
                scUnpackedVersion = GetScUnpackedVersion(applicationSettings.ScUnpackedRoot),
                syncHostEnabled = applicationSettings.SyncHostEnabled,
                syncHostBaseUrl = applicationSettings.SyncHostBaseUrl ?? string.Empty,
                syncHostTransportMode = applicationSettings.SyncHostTransportMode ?? "auto",
                syncHostPlayerHandle = applicationSettings.SyncHostPlayerHandle ?? string.Empty,
                syncHostOrganization = applicationSettings.SyncHostOrganization ?? string.Empty,
                syncHostClientId = syncHostIdentity.ClientId,
                syncHostClientFingerprint = syncHostIdentity.PublicKeyFingerprint,
                syncHostSignatureAlgorithm = syncHostIdentity.SignatureAlgorithm,
                uiLanguage = UiLocalizationCatalog.NormalizeLanguage(applicationSettings.UiLanguage),
                onlineProvider = "Star-Citizen.wiki API / starcitizen.tools media"
            },
            uiLanguage = UiLocalizationCatalog.NormalizeLanguage(applicationSettings.UiLanguage),
            uiText = UiLocalizationCatalog.BuildKeyMap(applicationSettings.UiLanguage),
            uiExactText = UiLocalizationCatalog.BuildExactTextMap(applicationSettings.UiLanguage),
            displaySettings = new
            {
                showStars = displaySettings.ShowStars,
                showPlanets = displaySettings.ShowPlanets,
                showStations = displaySettings.ShowStations,
                showSystemStations = displaySettings.ShowSystemStations,
                showMissionStations = displaySettings.ShowMissionStations,
                externalFreightElevatorsOnly = displaySettings.ExternalFreightElevatorsOnly,
                surfaceFreightElevatorsOnly = displaySettings.SurfaceFreightElevatorsOnly,
                surfaceVehicleServicesOnly = displaySettings.SurfaceVehicleServicesOnly,
                surfaceGaragesOnly = displaySettings.SurfaceGaragesOnly,
                surfaceLandingPadsOnly = displaySettings.SurfaceLandingPadsOnly,
                showRacingTracks = displaySettings.ShowRacingTracks,
                showJumpPoints = displaySettings.ShowJumpPoints,
                showOrbits = displaySettings.ShowOrbits,
                showAsteroids = displaySettings.ShowAsteroids,
                showLabels = displaySettings.ShowLabels,
                showRegions = displaySettings.ShowRegions,
                hidden = displaySettings.ShowHidden,
                backgroundStars = displaySettings.BackgroundStars,
                majorOnly = displaySettings.MajorOnly,
                guides = displaySettings.Guides,
                webglBodies = displaySettings.WebGlBodies,
                orbitPlane = displaySettings.OrbitPlane,
                surveyLighting = displaySettings.SurveyLighting
            },
            knowledgeSummary,
            knowledgeLocations = knowledgeLocations.Select(l => new
            {
                l.Uuid,
                l.Name,
                l.Description,
                l.Type,
                l.Subtype,
                l.System,
                l.ParentUuid,
                l.ParentName,
                l.ContainerName,
                l.JurisdictionUuid,
                l.JurisdictionName,
                l.FactionUuid,
                l.FactionName,
                l.FactionLinkAuthority,
                l.FactionDescription,
                l.FactionType,
                l.FactionClassification,
                FactionRelations = l.FactionRelations.Take(24),
                l.Services,
                l.Tags,
                l.Properties,
                TradeProfiles = l.TradeProfiles.Select(p => new { p.Uuid, p.ClassName, p.DisplayName, p.Disabled }),
                l.TradeProduces,
                l.TradeConsumes,
                CommoditiesSold = l.CommoditiesSold.Select(c => new { c.Uuid, c.Key, c.Name, c.LinkAuthority }),
                CommoditiesBought = l.CommoditiesBought.Select(c => new { c.Uuid, c.Key, c.Name, c.LinkAuthority }),
                RelatedItems = l.RelatedItems.Take(32),
                l.Hidden,
                l.QuantumTravelValid,
                l.PositionX,
                l.PositionY,
                l.PositionZ,
                l.SourcePath
            }),
            entityKnowledge = entityKnowledge.ToDictionary(
                x => x.Key,
                x => new { LocationUuid = x.Value.Location.Uuid, x.Value.LinkAuthority, x.Value.Confidence, x.Value.Evidence },
                StringComparer.OrdinalIgnoreCase),
            surfaceKnowledge = surfaceKnowledge.ToDictionary(
                x => x.Key,
                x => new { LocationUuid = x.Value.Location.Uuid, x.Value.LinkAuthority, x.Value.Confidence, x.Value.Evidence },
                StringComparer.OrdinalIgnoreCase),
            entities = dataset.Entities.Select(e => new
            {
                id = e.Id,
                system = e.System,
                uuid = e.SourceUuid,
                name = e.Name,
                type = e.Type,
                parentId = e.ParentId,
                parentUuid = e.ParentSourceUuid,
                sourcePath = e.SourcePath,
                entityClass = e.EntityClass,
                visualClass = MapVisualAssetResolver.Classify(e.Type, e.Name, e.EntityClass, e.SourcePath).ToString(),
                hidden = e.Hidden,
                qt = e.QuantumTravelValid,
                x = e.X,
                y = e.Y,
                z = e.Z,
                distanceToParent = e.DistanceToParentMeters,
                source = e.SourceAuthority,
                status = e.DataStatus
            }),
            infrastructure = dataset.Infrastructure.Select(x => new
            {
                placementId = x.PlacementId,
                system = x.System,
                infrastructureType = x.InfrastructureType,
                isPresent = x.IsPresent,
                count = x.Count,
                scUnpackedCorroborated = x.ScUnpackedCorroborated,
                scUnpackedEvidence = x.ScUnpackedEvidence,
                sourcePath = x.SourcePath,
                evidencePath = x.EvidencePath,
                sourceAuthority = x.SourceAuthority,
                dataStatus = x.DataStatus
            }),
            regions = dataset.Regions.Select(r => new
            {
                id = r.Id,
                name = r.Name,
                type = r.Type,
                centerX = r.CenterX,
                centerY = r.CenterY,
                centerZ = r.CenterZ,
                innerRadiusMeters = r.InnerRadiusMeters,
                outerRadiusMeters = r.OuterRadiusMeters,
                thicknessMeters = r.ThicknessMeters,
                densityScale = r.DensityScale,
                composition = r.Composition,
                dataStatus = r.DataStatus
            }),
            volumes = dataset.Volumes.Select(v => new
            {
                id = v.Id,
                name = v.Name,
                type = v.Type,
                centerX = v.CenterX,
                centerY = v.CenterY,
                centerZ = v.CenterZ,
                minLocalX = v.MinLocalX,
                minLocalY = v.MinLocalY,
                minLocalZ = v.MinLocalZ,
                maxLocalX = v.MaxLocalX,
                maxLocalY = v.MaxLocalY,
                maxLocalZ = v.MaxLocalZ,
                boundingRadiusMeters = v.BoundingRadiusMeters,
                renderAabb = !(v.TemplateSourcePath?.Contains("glaciemring_bg", StringComparison.OrdinalIgnoreCase) ?? false),
                dataStatus = v.DataStatus
            }),
            bodies = dataset.Bodies,
            surfaceTargets = surfaceTargets.Select(t =>
            {
                var racing = RacingTrackCatalog.Resolve(t);
                var map = SurfaceMapProjectionService.ProjectEquirectangular(
                    t.AxisLatitudeDegrees,
                    t.AxisLongitudeDegrees,
                    t.CoordinateConvention,
                    t.DataStatus);
                return new
                {
                    t.AnchorId,
                    t.System,
                    t.BodyName,
                    t.Name,
                    t.Category,
                    t.AnchorScope,
                    t.SourceUuid,
                    t.EntityClass,
                    t.BodyLocalX,
                    t.BodyLocalY,
                    t.BodyLocalZ,
                    t.ReferenceRadiusMeters,
                    t.AxisLatitudeDegrees,
                    t.AxisLongitudeDegrees,
                    t.AltitudeMeters,
                    t.CoordinateConvention,
                    t.SourcePath,
                    t.SourceAuthority,
                    t.DataStatus,
                    t.HiddenOnMap,
                    CanonicalUuid = racing?.ResolvedLocationUuid,
                    Description = racing?.Description,
                    Operator = racing?.Operator,
                    RacingLengthKm = racing?.LengthKm,
                    RacingFeatures = racing?.Features,
                    RacingSourceContract = racing?.SourceContract,
                    SemanticAuthority = racing?.SemanticAuthority,
                    MapX01 = map.X01,
                    MapY01 = map.Y01,
                    VisualClass = MapVisualAssetResolver.Classify(t.Category, t.Name, t.EntityClass, t.SourcePath).ToString(),
                    MapProjectionStatus = "AXIS_SPHERICAL_DIAGNOSTIC_NOT_GEOGRAPHICALLY_CALIBRATED"
                };
            }),
            surfaceBodies = dataset.SurfaceCoverage.Select(c => new
            {
                system = c.System,
                bodyName = c.BodyName,
                sourceUuid = c.BodySourceUuid,
                anchorCount = c.AnchorCount,
                nearSurfaceCount = c.NearSurfaceCount,
                elevatedCount = c.ElevatedAtmosphericCount,
                orbitalCount = c.OrbitalCount,
                subsurfaceCount = c.SubsurfaceCount,
                minAltitudeMeters = c.MinimumAltitudeMeters,
                maxAltitudeMeters = c.MaximumAltitudeMeters,
                coordinateConvention = c.CoordinateConvention,
                referenceRadiusMeters = dataset.Bodies.FirstOrDefault(b => b.Name.Equals(c.BodyName, StringComparison.OrdinalIgnoreCase))?.RadiusMeters,
                dataStatus = c.DataStatus
            }),
            surfaceTextures = dataset.Bodies.Select(body =>
            {
                var coverage = dataset.SurfaceCoverage.FirstOrDefault(c => c.BodyName.Equals(body.Name, StringComparison.OrdinalIgnoreCase));
                var sourceUuid = !string.IsNullOrWhiteSpace(body.SourceUuid) ? body.SourceUuid : coverage?.BodySourceUuid;
                var coordinateConvention = coverage?.CoordinateConvention ?? "BODY_LOCAL_ENGINE_AXES";
                var canonicalId = string.IsNullOrWhiteSpace(sourceUuid) ? $"body:{dataset.System}:{body.Name}" : $"uuid:{sourceUuid!.ToLowerInvariant()}";
                var descriptor = SurfaceTextureAssetResolver.Resolve(
                    Path.Combine(AppContext.BaseDirectory, "Assets", "MapVisuals"),
                    canonicalId,
                    body.Name,
                    coordinateConvention);

                var projection = descriptor.Projection;
                var assetPath = descriptor.AssetPath;
                var exists = descriptor.Exists;
                var browserAssetUrl = descriptor.Exists
                    ? $"https://starsync-assets/Surfaces/Overrides/by-canonical-id/{Uri.EscapeDataString(Path.GetFileName(descriptor.AssetPath))}"
                    : null;
                var pixelWidth = descriptor.PixelWidth;
                var pixelHeight = descriptor.PixelHeight;
                var sourceAuthority = descriptor.SourceAuthority;
                var dataStatus = descriptor.DataStatus;
                var assetKind = descriptor.Exists ? "USER_OR_INSTALLED_OVERRIDE" : "MISSING";

                if (!descriptor.Exists && liveSurfaceTextures.TryGetValue(body.Name, out var live))
                {
                    projection = live.Projection;
                    assetPath = live.AssetPath;
                    exists = true;
                    browserAssetUrl = "https://starsync-live-textures/" + string.Join("/", live.BrowserRelativePath.Split('/').Select(Uri.EscapeDataString));
                    pixelWidth = live.PixelWidth;
                    pixelHeight = live.PixelHeight;
                    sourceAuthority = live.SourceAuthority;
                    dataStatus = live.DataStatus;
                    assetKind = live.AssetKind;
                }

                liveSurfaceTextures.TryGetValue(body.Name, out var selectedLiveTexture);
                return new
                {
                    BodyCanonicalId = descriptor.BodyCanonicalId,
                    BodyName = descriptor.BodyName,
                    Projection = projection,
                    AssetPath = assetPath,
                    Exists = exists,
                    BrowserAssetUrl = browserAssetUrl,
                    PixelWidth = pixelWidth,
                    PixelHeight = pixelHeight,
                    CoordinateConvention = descriptor.CoordinateConvention,
                    SourceAuthority = sourceAuthority,
                    DataStatus = dataStatus,
                    AssetKind = assetKind,
                    SelectionReason = selectedLiveTexture?.SelectionReason,
                    CloudBrowserAssetUrl = selectedLiveTexture?.CloudBrowserRelativePath is { Length: > 0 } cloudRelative
                        ? "https://starsync-live-textures/" + string.Join("/", cloudRelative.Split('/').Select(Uri.EscapeDataString))
                        : null,
                    CloudAssetKind = selectedLiveTexture?.CloudAssetKind ?? "NONE",
                    AtmosphereStrength = selectedLiveTexture?.AtmosphereStrength ?? 0.0,
                    AtmosphereExtent = selectedLiveTexture?.AtmosphereExtent ?? 1.0,
                    AtmosphereR = selectedLiveTexture?.AtmosphereR ?? 0.42,
                    AtmosphereG = selectedLiveTexture?.AtmosphereG ?? 0.78,
                    AtmosphereB = selectedLiveTexture?.AtmosphereB ?? 1.0,
                    CloudOpacity = selectedLiveTexture?.CloudOpacity ?? 0.0,
                    ReliefStrength = selectedLiveTexture?.ReliefStrength ?? 0.0,
                    NormalBrowserAssetUrl = selectedLiveTexture?.NormalBrowserRelativePath is { Length: > 0 } normalRelative
                        ? "https://starsync-live-textures/" + string.Join("/", normalRelative.Split('/').Select(Uri.EscapeDataString))
                        : null,
                    NormalAssetKind = selectedLiveTexture?.NormalAssetKind ?? "NONE",
                    NormalStrength = selectedLiveTexture?.NormalStrength ?? 0.0,
                    OverviewBrowserAssetUrl = descriptor.Exists
                        ? browserAssetUrl
                        : selectedLiveTexture?.OverviewBrowserRelativePath is { Length: > 0 } overviewRelative
                            ? "https://starsync-live-textures/" + string.Join("/", overviewRelative.Split('/').Select(Uri.EscapeDataString))
                            : browserAssetUrl,
                    OverviewPixelWidth = selectedLiveTexture?.OverviewPixelWidth ?? pixelWidth,
                    OverviewPixelHeight = selectedLiveTexture?.OverviewPixelHeight ?? pixelHeight
                };
            }),
            catalog = UniverseCatalogBuilder.Build(dataset),
            routeTargets = allDatasets.Values
                .SelectMany(d => UniverseCatalogBuilder.Build(d)
                    .Where(c => !c.Hidden || c.Category.Equals("JumpPoint", StringComparison.OrdinalIgnoreCase) || c.Category.Equals("Gateway", StringComparison.OrdinalIgnoreCase))
                    .Select(c => new
                    {
                        system = d.System,
                        placementId = c.PlacementId,
                        name = c.Name,
                        category = c.Category,
                        type = c.Type,
                        qt = c.QuantumTravelValid,
                        x = c.X,
                        y = c.Y,
                        z = c.Z,
                        coordinateKind = "PLACEMENT_SNAPSHOT_XYZ",
                        surfaceAnchorId = (string?)null,
                        bodyName = (string?)null,
                        dataStatus = c.DataStatus
                    })
                    .Concat(SurfaceTargetCatalogBuilder.Build(d).Select(t => new
                    {
                        system = d.System,
                        placementId = t.AnchorId,
                        name = t.Name,
                        category = t.Category,
                        type = t.AnchorScope,
                        qt = false,
                        x = t.BodyLocalX,
                        y = t.BodyLocalY,
                        z = t.BodyLocalZ,
                        coordinateKind = "BODY_FIXED_XYZ",
                        surfaceAnchorId = (string?)t.AnchorId,
                        bodyName = (string?)t.BodyName,
                        dataStatus = t.DataStatus
                    })))
                .OrderBy(x => x.system, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.name, StringComparer.OrdinalIgnoreCase),
            initialNavigationStart = initialNavigationStart is null ? null : new
            {
                id = initialNavigationStart.PlacementId,
                system = initialNavigationStart.System,
                name = initialNavigationStart.Label,
                x = initialNavigationStart.X,
                y = initialNavigationStart.Y,
                z = initialNavigationStart.Z,
                coordinateKind = initialNavigationStart.CoordinateKind,
                surfaceAnchorId = initialNavigationStart.SurfaceAnchorId,
                bodyName = initialNavigationStart.BodyName,
                status = initialNavigationStart.DataStatus
            },
            initialNavigationDestination = initialNavigationDestination is null ? null : new
            {
                id = initialNavigationDestination.PlacementId,
                system = initialNavigationDestination.System,
                name = initialNavigationDestination.Label,
                x = initialNavigationDestination.X,
                y = initialNavigationDestination.Y,
                z = initialNavigationDestination.Z,
                coordinateKind = initialNavigationDestination.CoordinateKind,
                surfaceAnchorId = initialNavigationDestination.SurfaceAnchorId,
                bodyName = initialNavigationDestination.BodyName,
                status = initialNavigationDestination.DataStatus
            },
            bookmarks = bookmarks.Select(b => new
            {
                b.Id,
                b.Name,
                b.System,
                b.ReferenceFrameId,
                b.CoordinateKind,
                b.X,
                b.Y,
                b.Z,
                b.BodySourceUuid,
                b.LatitudeDegrees,
                b.LongitudeDegrees,
                b.AltitudeMeters,
                b.Tags,
                b.Visibility,
                b.Revision,
                b.CreatedUtc,
                b.UpdatedUtc,
                b.Category,
                b.Note,
                b.Color,
                b.ShowOnMap,
                b.BookmarkScope,
                b.CreatorClientId,
                b.ContentFingerprint
            }),
            bookmarkGroups = bookmarkGroups.Select(g => new
            {
                g.Id,
                g.Name,
                g.Description,
                g.BookmarkIds,
                g.CreatorClientId,
                g.Revision,
                g.CreatedUtc,
                g.UpdatedUtc,
                g.ContentFingerprint,
                g.ShareStatus
            }),
            locationOverrides = locationOverrides.Select(o => new
            {
                o.Key,
                o.Name,
                o.LocationUuid,
                o.PlacementId,
                o.SurfaceAnchorId,
                o.Description,
                imageUrl = o.BrowserImageUrl,
                o.UpdatedUtc
            }),
            galaxySchematic = galaxySchematic.Select(g => new
            {
                system = g.System,
                x = g.DisplayX,
                y = g.DisplayY,
                z = g.DisplayZ,
                anchorSystem = g.AnchorSystem,
                viaJumpConnectionId = g.DerivedFromJumpConnectionId,
                coordinateMeaning = g.CoordinateMeaning,
                distanceMeaning = g.DistanceMeaning,
                sourceAuthority = g.SourceAuthority,
                dataStatus = g.DataStatus
            }),
            jumpConnections = jumpConnections.Select(j => new
            {
                id = j.ConnectionId,
                systemA = j.SystemA,
                systemB = j.SystemB,
                traversable = j.Traversable,
                status = j.DataStatus
            }),
            simulatedOrbits = dataset.SimulatedOrbits
        });

        var html = """
<!doctype html>
<html>
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline' https://starsync-assets; style-src 'unsafe-inline'; img-src data: https://starsync-assets https://starsync-branding https://starsync-location-images https://starsync-location-overrides https://starsync-live-textures; connect-src 'none'; object-src 'none'; frame-src 'none'; base-uri 'none'; form-action 'none'" />
<style>
