cing:.055em;color:#78dfff}.systemHero .sub{margin-top:6px;font-size:9px;letter-spacing:.18em;color:#4dacc1}.systemHeroOverview{margin-top:10px;width:100%;padding:9px 10px 8px;border-left:2px solid rgba(79,188,215,.62);background:linear-gradient(90deg,rgba(2,16,22,.86),rgba(2,16,22,.50) 72%,rgba(2,16,22,0));box-sizing:border-box;text-shadow:0 1px 7px #000}.systemHeroDescription{font-size:10px;line-height:1.42;color:#bad3dc;margin-bottom:8px;max-width:390px}.systemHeroFacts{display:grid;grid-template-columns:1fr 1fr;gap:4px 14px;margin-bottom:8px}.systemHeroFact{min-width:0}.systemHeroFact .k{display:block;color:#5e91a3;font-size:8px;letter-spacing:.12em;text-transform:uppercase}.systemHeroFact .v{display:block;color:#dff7fb;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.systemHeroStats{display:grid;grid-template-columns:repeat(6,minmax(42px,1fr));gap:5px;border-top:1px solid rgba(57,119,139,.32);padding-top:7px}.systemHeroStat{text-align:left}.systemHeroStat .n{display:block;font-size:15px;font-weight:700;line-height:1;color:#e8fbff}.systemHeroStat .l{display:block;margin-top:3px;font-size:7px;line-height:1.1;letter-spacing:.08em;text-transform:uppercase;color:#6ea4b6}.systemHeroSource{margin-top:6px;font-size:7px;letter-spacing:.08em;color:#547886}.systemHero.hidden{display:none}.mapCornerBadge{position:absolute;right:76px;top:18px;z-index:6;font-size:9px;letter-spacing:.1em;color:#6cc9da;border:1px solid #1b6072;background:#04131baa;padding:5px 8px;pointer-events:none}
.workspacePanel{position:absolute;inset:46px 42px 42px 42px;z-index:24;display:none;background:linear-gradient(160deg,rgba(4,22,31,.985),rgba(1,9,14,.992)),repeating-linear-gradient(180deg,rgba(83,220,238,.016) 0,rgba(83,220,238,.016) 1px,transparent 1px,transparent 4px);border:1px solid #23788d;box-shadow:0 24px 80px #000e,0 0 30px rgba(31,190,214,.16),inset 0 0 34px rgba(53,193,216,.03);backdrop-filter:blur(9px);overflow:hidden;clip-path:polygon(0 0,calc(100% - 16px) 0,100% 16px,100% 100%,16px 100%,0 calc(100% - 16px))}.workspacePanel.open{display:grid;grid-template-rows:44px 1fr}.workspaceHead{display:flex;align-items:center;gap:12px;padding:0 14px;border-bottom:1px solid #23657a;background:linear-gradient(90deg,rgba(8,37,49,.98),rgba(4,21,29,.96));box-shadow:inset 0 -1px rgba(90,224,241,.05)}.workspaceTitle{font-size:14px;font-weight:700;letter-spacing:.11em;color:#93ebf6;text-transform:uppercase;text-shadow:0 0 10px rgba(66,216,236,.27)}.workspaceHead .muted{flex:1}.workspaceClose{margin-left:auto;padding:4px 9px}.workspaceBody{overflow:auto;padding:14px}.workspaceGrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}.workspaceCard{position:relative;border:1px solid #195063;background:linear-gradient(165deg,rgba(5,24,33,.96),rgba(2,14,20,.975));padding:10px;box-shadow:inset 0 0 18px rgba(57,191,213,.025)}.workspaceCard::before{content:'';position:absolute;left:8px;top:3px;width:42%;height:1px;background:linear-gradient(90deg,rgba(104,229,243,.62),transparent);pointer-events:none}.workspaceCard h4{margin:0 0 8px;color:#7fe1ee;text-transform:uppercase;font-size:10px;letter-spacing:.095em;text-shadow:0 0 8px rgba(53,207,227,.19)}.workspaceTable{width:100%;border-collapse:collapse;font-size:10px}.workspaceTable th,.workspaceTable td{padding:5px 7px;border-bottom:1px solid #102d3a;text-align:left}.workspaceTable th{position:sticky;top:0;background:#071a24;color:#83d7ec}.workspaceTable tr:hover td{background:#0a2531}.workspaceToolbar{display:flex;gap:8px;align-items:center;margin-bottom:10px}.workspaceToolbar input,.workspaceToolbar select{margin:0}.workspaceStat{font-size:22px;color:#dff9ff;font-variant-numeric:tabular-nums}.workspaceNote{font-size:10px;color:#7796a6;line-height:1.5}.workspaceSubcard{margin-top:8px;border:1px solid #18485a;background:#041019;padding:7px 9px}.workspaceSubcard summary{cursor:pointer;color:#8bdff0;font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase}.workspaceSubcard[open] summary{margin-bottom:8px;padding-bottom:6px;border-bottom:1px solid #123847}.diagnosticsCard{grid-column:1/-1}.diagnosticsResults{display:grid;gap:3px}.diagCheck{border:1px solid #173b49;background:#041019;padding:7px 9px}.diagCheck .diagHead{display:flex;justify-content:space-between;gap:14px;align-items:flex-start;font-size:10px;font-weight:700}.diagCheck .diagMessage{margin-top:4px;color:#7891a5;font-size:9.5px;line-height:1.45;overflow-wrap:anywhere;word-break:break-word}.diagCheck.ok{border-color:#215b43;background:#04140f}.diagCheck.ok .diagHead,.diagCheck.ok .diagStatus{color:#72d49c}.diagCheck.missing{border-color:#283d48;background:#071018}.diagCheck.missing .diagHead,.diagCheck.missing .diagStatus{color:#8296a2}.diagCheck.bad{border-color:#6f3034;background:#18090b}.diagCheck.bad .diagHead,.diagCheck.bad .diagStatus{color:#ef8087}.diagCheck.warn{border-color:#76562c;background:#171005}.diagCheck.warn .diagHead,.diagCheck.warn .diagStatus{color:#e7ba6d}.diagPath{display:block;margin-top:2px;font-family:Consolas,monospace;font-size:9px;color:#89a8b6;overflow-wrap:anywhere;word-break:break-all}
