<body>
<div id="root">
<header><div class="brandBlock"><span class="brandGlyph">☰</span><span class="brandMark">SSU</span><span class="brandSlash"></span><span class="brandTitle">Universe Map</span></div><div class="topCenter"><div class="topMeta"><span id="systemLabel"></span><span class="ok">LIVE · CURRENT DATA</span><span id="renderStatus" class="muted"></span><span id="zoomText"></span></div><div class="mapTabs"><button id="tabGlx" class="mapTab">GLX</button><button id="tabSys" class="mapTab active">SYS</button><button id="tabObj" class="mapTab">OBJ</button></div></div><div class="headerStatus"><span class="headerPill" id="modeStatus">SYSTEM</span><span id="authorityStatus">AUTHORITATIVE POSITIONS</span></div></header>
<aside id="left">
 <div class="section displaySection"><h3>◉ Display</h3>
  <label class="displayRow"><input id="showStars" type="checkbox" checked><span>Stars</span><span class="displayIcon">✹</span></label>
  <label class="displayRow"><input id="showPlanets" type="checkbox" checked><span>Planets &amp; Moons</span><span class="displayIcon">◉</span></label>
  <label class="displayRow"><input id="showStations" type="checkbox" checked><span>Stations</span><span class="displayIcon">✥</span></label>
  <label class="displayRow sub"><input id="showSystemStations" type="checkbox" checked><span>System Stations</span><span class="displayIcon">◆</span></label>
  <label class="displayRow sub"><input id="showMissionStations" type="checkbox"><span>Mission / Event Stations</span><span class="displayIcon">◇</span></label>
  <div class="displayGroupLabel">Orbital station filters</div>
  <label class="displayRow sub"><input id="externalFreightElevatorsOnly" type="checkbox"><span>Has external freight elevator</span><span class="displayIcon">F</span></label>
  <div class="displayGroupLabel">Ground location filters</div>
  <label class="displayRow sub"><input id="surfaceFreightElevatorsOnly" type="checkbox"><span>Has freight elevator</span><span class="displayIcon">F</span></label>
  <label class="displayRow sub"><input id="surfaceVehicleServicesOnly" type="checkbox"><span>Has Vehicle Services</span><span class="displayIcon">V</span></label>
  <label class="displayRow sub"><input id="surfaceGaragesOnly" type="checkbox"><span>Has Garage</span><span class="displayIcon">G</span></label>
  <label class="displayRow sub"><input id="surfaceLandingPadsOnly" type="checkbox"><span>Has Landing Pad</span><span class="displayIcon">P</span></label>
  <label class="displayRow"><input id="showRacingTracks" type="checkbox" checked><span>Racing Tracks</span><span class="displayIcon">R</span></label>
  <label class="displayRow"><input id="showJumpPoints" type="checkbox" checked><span>Jump Points</span><span class="displayIcon">△</span></label>
  <label class="displayRow"><input id="showOrbits" type="checkbox" checked><span>Orbits</span><span class="displayIcon">◌</span></label>
  <label class="displayRow"><input id="showAsteroids" type="checkbox" checked><span>Asteroid Fields</span><span class="displayIcon">✦</span></label>
  <label class="displayRow"><input id="showLabels" type="checkbox" checked><span>Labels</span><span class="displayIcon">⌑</span></label>
  <label class="displayRow"><input id="showRegions" type="checkbox"><span>Region Boundaries</span><span class="displayIcon">◌</span></label>
  <label class="displayRow"><input id="hidden" type="checkbox"><span>Show Hidden</span><span class="displayIcon">◈</span></label>
  <label class="displayRow"><input id="backgroundStars" type="checkbox" checked><span>Background Nebula</span><span class="displayIcon">✣</span></label>
  <div class="internalControls" hidden><input id="catalogSearch" type="hidden" value=""><select id="catalogCategory"><option value="All" selected>All</option></select><span id="catalogCount"></span><input id="majorOnly" type="checkbox" checked><input id="guides" type="checkbox" checked><input id="webglBodies" type="checkbox" checked><input id="orbitPlane" type="checkbox" checked><input id="surveyLighting" type="checkbox"><input id="surveyNightFilter" type="checkbox" checked><select id="catalogMapMode"><option value="highlight" selected>Highlight matches</option><option value="filter">Filter map to matches</option></select><select id="focusMode"><option value="parent" selected>Object + parent / orbit</option><option value="close">Object close</option></select><select id="focusMargin"><option value="1.25" selected>Default</option></select><button id="reset" type="button">Reset camera</button></div>
 </div>
 <div class="section"><h3>▣ Data status</h3><div id="stats"></div></div>
 <div class="section"><h3>◉ Planets</h3><div id="planetQuickList" class="planetQuickList"></div></div>
 <div class="section"><div class="sectionHeader"><h3>◈ Objects</h3><button id="objectListToggle" class="collapseButton" title="Collapse / expand results">▸</button></div><div id="objectSummary" class="objectSummary"></div><div id="objectList"></div></div>
 <div class="section"><div class="sectionHeader"><h3>◎ Body targets</h3><button id="surfaceListToggle" class="collapseButton" title="Collapse / expand body targets">▾</button></div><div id="surfaceControls"><select id="surfaceBody"></select><select id="surfaceCategory"><option>All</option></select><select id="surfaceViewMode"><option value="globe">Body-local 3D</option><option value="map">2D surface map</option></select><div id="surfaceCount" hidden></div><div id="surfaceMapAuthority" hidden></div><button id="openBodyView" hidden>Open body view</button><button id="returnSystemView" hidden>System view</button></div><div id="surfaceList"></div></div>
 <div class="leftBrandMark" aria-hidden="true"></div>
</aside>
<div id="mapWrap"><button id="toggleLeft" class="sideToggle left" title="Menu ein-/ausblenden">↔</button><button id="toggleRight" class="sideToggle right" title="Details ein-/ausblenden">↔</button><button id="galaxyButton" class="mapHierarchy systemMode" title="System / Galaxy transition">SYS → GLX</button><div id="focusZoomControl" class="focusZoomControl"><span>ZOOM</span><input id="focusZoomSlider" type="range" min="0" max="100" value="16" step="1"><span id="focusZoomValue" class="value">1.0×</span><button id="resetCameraTop" type="button">Reset camera</button></div><div id="lightingModeControl" class="lightingModeControl" title="Body lighting mode"><button id="stellarLightingButton" type="button" data-mode="stellar">STELLAR LIGHTING</button><button id="surveyLightingButton" type="button" data-mode="survey">SURVEY LIGHTING</button></div><div id="systemHero" class="systemHero"><div id="systemHeroTitle" class="title"></div><div id="systemHeroSub" class="sub">CURRENT LIVE SYSTEM · AUTHORITATIVE PLACEMENTS</div><div id="systemHeroOverview" class="systemHeroOverview" hidden><div id="systemHeroDescription" class="systemHeroDescription"></div><div id="systemHeroFacts" class="systemHeroFacts"></div><div id="systemHeroStats" class="systemHeroStats"></div><div id="systemHeroSource" class="systemHeroSource"></div></div></div><canvas id="glmap"></canvas><canvas id="map"></canvas><div id="workspacePanel" class="workspacePanel"><div class="workspaceHead"><div id="workspaceTitle" class="workspaceTitle">Workspace</div><div id="workspaceSubtitle" class="muted"></div><button id="workspaceClose" class="workspaceClose">✕</button></div><div id="workspaceBody" class="workspaceBody"></div></div><div id="tooltip"></div><div id="cursorCoords"></div><div id="measureLabel" class="measureLabel"></div><div id="contextMenu"><button id="ctxStart">SET / START</button><button id="ctxDestination">SET / DESTINATION</button><button id="ctxBookmark">BOOKMARK / SAVE</button><button id="ctxBookmarkEdit" style="display:none">BOOKMARK / EDIT</button><button id="ctxBookmarkDelete" style="display:none">BOOKMARK / DELETE</button><button id="ctxDirect">MODE / DIRECT LINE</button><button id="ctxRoute">MODE / ROUTE</button><button id="ctxUnsetZoom">VIEW / UNSET FOCUS</button><button id="ctxClear">NAV / CLEAR</button><div class="contextMenuFooter"><span id="ctxClock" class="ctxClock">--:--:--</span><span id="ctxCoords" class="ctxCoords">SYSTEM</span></div></div><div id="bookmarkModal" class="modalShade"><div class="modalCard"><h3 id="bookmarkModalTitle">Save bookmark</h3><div id="bookmarkScopeLabel" class="muted" style="margin-bottom:8px"></div><label>Name<input id="bookmarkModalName" type="text"></label><label>Category<select id="bookmarkModalCategory"><option>Mineralien</option><option>Infos</option><option>Material</option><option>Gefahr</option><option>Piraten</option><option>Basis</option><option>Sammelpunkt</option></select></label><label>Freitext<textarea id="bookmarkModalNote" rows="4"></textarea></label><label>Farbe<input id="bookmarkModalColor" type="color" value="#f59e0b"></label><label><input id="bookmarkModalShow" type="checkbox" checked> Auf der Map anzeigen</label><div id="bookmarkModalCoordinates" class="coordBlock"></div><div style="margin-top:9px;text-align:right"><button id="bookmarkModalCancel">Cancel</button><button id="bookmarkModalSave" style="margin-left:6px">Save</button></div></div></div><div id="hint">Wheel: zoom to cursor · left-drag: pan · middle-drag: orbit/tilt around selection/cursor · right-click: navigation / bookmark · double-click: focus</div><div id="mapLegendDock" class="mapLegendDock"><span class="mapLegendTitle">MAP LEGEND</span><div id="mapLegend" class="legend"></div></div></div>
<aside id="details"><div id="selectedObjectSection" class="section"><h3>◉ Selected object</h3><div id="detailBody" class="muted">Click an object.</div></div><div class="section"><h3>⌁ Measurement / Route</h3><div id="measurementBody" class="muted">Right-click an object and set Start / Destination.</div><div style="margin-top:8px;border-top:1px solid #173044;padding-top:8px"><div class="muted" style="font-size:10px;margin-bottom:5px">Destination</div><div class="predictionWrap"><input id="globalRouteSearch" type="search" autocomplete="off" placeholder="Search all systems, objects, locations…"><div id="globalRouteSuggestions" class="predictionList"></div></div><select id="globalRouteTarget" hidden></select><div style="display:flex;gap:6px"><button id="setGlobalDestination" hidden>Set destination</button><button id="calculateRoute">⌁ Calculate Route</button></div></div></div><div class="section"><h3>◈ Regions</h3><div id="regionBody"></div></div><div class="section"><h3>⌖ Surface locations</h3><input id="selectedSurfaceSearch" type="search" placeholder="Filter surface locations…"><div id="selectedSurfaceCount" class="muted" style="font-size:10px;margin-bottom:5px"></div><div id="selectedSurfaceLocations" class="muted">Select a planet or moon.</div></div><div class="section"><h3>★ Bookmarks</h3><div class="muted" style="font-size:10px;margin-bottom:6px">Right-click map → Save › Bookmark. Position uses the selected object when active, otherwise the cursor point.</div><div style="display:flex;gap:6px;margin-bottom:6px"><button id="bookmarkManagerButton" style="flex:1">Bookmark Manager</button><button id="bookmarkPublishButton" title="Open Bookmark Manager sharing controls">Share</button></div><input id="bookmarkSearch" type="search" placeholder="Filter bookmarks…"><div id="bookmarkCount" class="muted" style="font-size:10px;margin-bottom:5px"></div><div id="bookmarkList" class="muted">No bookmarks.</div></div></aside>
</div>
