<script>window.addEventListener('error',function(e){try{if(window.chrome&&window.chrome.webview)window.chrome.webview.postMessage({type:'rendererError',message:String(e.message||'JavaScript error'),line:e.lineno||0,column:e.colno||0})}catch(_){}});</script>
<script>
const data=__PAYLOAD__;
const uiLanguage=String(data.uiLanguage||data.applicationSettings?.uiLanguage||'en').toLowerCase()==='de'?'de':'en';
const uiText=data.uiText||{};
const uiExactText=data.uiExactText||{};
function uiT(key,fallback=''){return uiText[key]||fallback||key}
function uiChoice(english,german){return uiLanguage==='de'?german:english}
function translateExactText(value){
 const key=String(value??'').trim();
 if(Object.prototype.hasOwnProperty.call(uiExactText,key))return uiExactText[key];
 // Section headers carry decorative glyph prefixes. Preserve the glyph and translate only a known
 // UI caption suffix. This runs exclusively on application UI nodes, never arbitrary game values.
 for(const source of Object.keys(uiExactText).sort((a,b)=>b.length-a.length)){
  if(source.length<3||!key.endsWith(source))continue;
  const prefix=key.slice(0,key.length-source.length);
  if(prefix&&!/[A-Za-z0-9ÄÖÜäöüß]/.test(prefix))return prefix+uiExactText[source];
 }
 return value;
}
function translateUiNode(rootNode=document){
 const rootEl=rootNode?.nodeType===1?rootNode:document;
 const selectors='button,h3,h4,summary,th,.routeLabel,.displayGroupLabel,.displayRow>span:nth-child(2),.mapLegendTitle,.legend div,.systemHeroFact .k,.workspaceTitle,.workspaceNote,.muted,.sectionHeader h3,.row>span:first-child';
 for(const el of rootEl.querySelectorAll?.(selectors)||[]){
  for(const node of [...el.childNodes])if(node.nodeType===Node.TEXT_NODE){const raw=node.nodeValue||'';const trimmed=raw.trim();if(!trimmed)continue;const translated=translateExactText(trimmed);if(translated!==trimmed)node.nodeValue=raw.replace(trimmed,translated)}
 }
 for(const el of rootEl.querySelectorAll?.('input[placeholder],textarea[placeholder],[title]')||[]){
  if(el.hasAttribute('placeholder')){const v=el.getAttribute('placeholder');const t=translateExactText(v);if(t!==v)el.setAttribute('placeholder',t)}
  if(el.hasAttribute('title')){const v=el.getAttribute('title');const t=translateExactText(v);if(t!==v)el.setAttribute('title',t)}
 }
 for(const label of rootEl.querySelectorAll?.('label')||[]){
  for(const node of [...label.childNodes])if(node.nodeType===Node.TEXT_NODE){const raw=node.nodeValue||'';const trimmed=raw.trim();if(!trimmed)continue;const translated=translateExactText(trimmed);if(translated!==trimmed)node.nodeValue=raw.replace(trimmed,translated)}
 }
}
const uiLocalizationObserver=new MutationObserver(mutations=>{for(const m of mutations)for(const n of m.addedNodes)if(n.nodeType===1)translateUiNode(n)});
const persistedDisplaySettings=data.displaySettings||{};
const persistedDisplayIds=['showStars','showPlanets','showStations','showSystemStations','showMissionStations','externalFreightElevatorsOnly','surfaceFreightElevatorsOnly','surfaceVehicleServicesOnly','surfaceGaragesOnly','surfaceLandingPadsOnly','showRacingTracks','showJumpPoints','showOrbits','showAsteroids','showLabels','showRegions','hidden','backgroundStars','majorOnly','guides','webglBodies','orbitPlane','surveyLighting','surveyNightFilter'];
for(const id of persistedDisplayIds){const el=document.getElementById(id),value=persistedDisplaySettings[id];if(el&&typeof value==='boolean')el.checked=value;}
function persistDisplaySettings(){if(!window.chrome?.webview)return;const values={};for(const id of persistedDisplayIds){const el=document.getElementById(id);if(el)values[id]=el.checked===true;}window.chrome.webview.postMessage({type:'displaySettingsUpdate',...values});}
document.getElementById('systemLabel').textContent=(data.system||'unknown').toUpperCase()+' / LIVE DATA';document.getElementById('systemHeroTitle').textContent=(data.system||'unknown').toUpperCase()+' SYSTEM';
const systemOverview=data.systemOverview||null,systemHeroOverview=document.getElementById('systemHeroOverview');
if(systemOverview){const description=document.getElementById('systemHeroDescription'),facts=document.getElementById('systemHeroFacts'),stats=document.getElementById('systemHeroStats'),source=document.getElementById('systemHeroSource');description.textContent=systemOverview.Description||'';facts.innerHTML=[['Affiliation',systemOverview.Affiliation],['Jurisdiction',systemOverview.Jurisdiction],['Size',systemOverview.Size],['Star type',systemOverview.StarType]].filter(x=>x[1]).map(x=>`<div class="systemHeroFact"><span class="k">${htmlEsc(x[0])}</span><span class="v">${htmlEsc(x[1])}</span></div>`).join('');stats.innerHTML=(systemOverview.Stats||[]).map(x=>`<div class="systemHeroStat"><span class="n">${Number(x.Value||0)}</span><span class="l">${htmlEsc(x.Label||x.Key||'')}</span></div>`).join('');let checked='';try{checked=systemOverview.SourceCheckedUtc?new Date(systemOverview.SourceCheckedUtc).toISOString().slice(0,10):''}catch{}source.textContent=`SOURCE · ${systemOverview.SourceName||'community reference'}${checked?' · checked '+checked:''}`;systemHeroOverview.hidden=false}
const root=document.getElementById('root'),canvas=document.getElementById('map'),glCanvas=document.getElementById('glmap'),ctx=canvas.getContext('2d'),wrap=document.getElementById('mapWrap');
const glRenderer=window.StarSyncWebGL?.create(glCanvas)||{available:false,error:'WebGL bridge unavailable',resize(){},clear(){},drawBody(){return false},releaseTexture(){},dispose(){}};
const focusZoomControl=document.getElementById('focusZoomControl'),focusZoomSlider=document.getElementById('focusZoomSlider'),focusZoomValue=document.getElementById('focusZoomValue'),lightingModeControl=document.getElementById('lightingModeControl'),stellarLightingButton=document.getElementById('stellarLightingButton'),surveyLightingButton=document.getElementById('surveyLightingButton'),surveyLightingToggle=document.getElementById('surveyLighting');
window.addEventListener('beforeunload',()=>{try{uiLocalizationObserver.disconnect()}catch{}try{glRenderer.dispose?.()}catch{}});
let glTexturedBodyIds=new Set(),glProceduralEntityIds=new Set();
