 const ids=()=>[...bookmarkSelection];document.getElementById('wsBmAssign').onclick=()=>{const target=document.getElementById('wsBmTargetGroup').value;if(target&&ids().length)bookmarkGroupRequest('assign',{id:target,bookmarkIds:ids()})};
 if(group){document.getElementById('wsBmMove').onclick=()=>{const target=document.getElementById('wsBmTargetGroup').value;if(target&&target!==group.Id&&ids().length)bookmarkGroupRequest('move',{sourceId:group.Id,targetId:target,bookmarkIds:ids()})};document.getElementById('wsBmRemove').onclick=()=>{if(ids().length)bookmarkGroupRequest('remove',{id:group.Id,bookmarkIds:ids()})};document.getElementById('wsBmPublish').onclick=()=>bookmarkGroupRequest('publish',{id:group.Id});}
 document.getElementById('wsBmApplyCategory').onclick=()=>{if(ids().length)bookmarkBatchRequest('update',ids(),{category:document.getElementById('wsBmCategory').value})};document.getElementById('wsBmShow').onclick=()=>{if(ids().length)bookmarkBatchRequest('update',ids(),{showOnMap:true})};document.getElementById('wsBmHide').onclick=()=>{if(ids().length)bookmarkBatchRequest('update',ids(),{showOnMap:false})};document.getElementById('wsBmDeleteSelected').onclick=()=>{if(ids().length&&confirm(`Delete ${ids().length} selected bookmark(s)?`))bookmarkBatchRequest('delete',ids())};
}
function workspaceSettings(){
 workspaceTitle.textContent='Settings';workspaceSubtitle.textContent='Renderer, visibility and optional data sources';
 const setting=(id,label)=>`<label class="displayRow"><input data-setting="${id}" type="checkbox" ${document.getElementById(id).checked?'checked':''}><span>${label}</span><span class="displayIcon">*</span></label>`;
 const app=data.applicationSettings||{};
 workspaceBody.innerHTML=`<div class="workspaceGrid">
  <div class="workspaceCard"><h4>${uiT('settings.interface','Interface')}</h4><div class="workspaceNote">${uiT('settings.interfaceNote','UI language affects application controls only. Game object content always remains native.')}</div><label style="margin-top:9px">${uiT('ui.language','Language')}<select id="wsUiLanguage"><option value="en">${uiT('ui.english','English')}</option><option value="de">${uiT('ui.german','German')}</option></select></label></div>
  <div class="workspaceCard"><h4>Visibility</h4>${setting('showStars','Stars')}${setting('showPlanets','Planets & Moons')}${setting('showStations','Stations')}${setting('showSystemStations','System Stations')}${setting('showMissionStations','Mission / Event Stations')}<div class="workspaceNote" style="margin:7px 0 3px">Orbital station filters</div>${setting('externalFreightElevatorsOnly','Has external freight elevator')}<div class="workspaceNote" style="margin:7px 0 3px">Ground location filters</div>${setting('surfaceFreightElevatorsOnly','Has freight elevator')}${setting('surfaceVehicleServicesOnly','Has Vehicle Services')}${setting('surfaceGaragesOnly','Has Garage')}${setting('surfaceLandingPadsOnly','Has Landing Pad')}${setting('showRacingTracks','Racing Tracks')}${setting('showJumpPoints','Jump Points')}${setting('showOrbits','Orbits')}${setting('showAsteroids','Asteroid Fields')}${setting('showLabels','Labels')}${setting('showRegions','Region Boundaries')}${setting('hidden','Show Hidden')}${setting('backgroundStars','Background Nebula')}</div>
  <div class="workspaceCard"><h4>Optional data-source adapters</h4><div class="workspaceNote">${htmlEsc(uiT('note.optionalAdapters','StarSyncUniverse always uses the packaged body-presentation textures. The adapters below only refresh world data or enrich metadata; disabling them never disables planet/moon textures.'))}</div>
  <details class="workspaceSubcard" open><summary>Local Data.p4k / StarBreaker</summary><label class="displayRow"><input id="wsLocalP4k" type="checkbox"><span>Enable local Data.p4k update adapter</span><span class="displayIcon">P</span></label><div class="workspaceNote">${htmlEsc(uiT('note.starbreakerInstall','Preferred installation: copy starbreaker.exe into the StarSyncUniverse application directory (a direct child or subdirectory is auto-detected). If no executable is found, configure its full path below. When enabled, StarSyncUniverse invokes StarBreaker against the configured Star Citizen LIVE Data.p4k, rebuilds authoritative placement/object data and refreshes presentation caches. After a Star Citizen update, the next reload reads the updated Data.p4k again; if the game data format requires a newer StarBreaker, replace starbreaker.exe and reload.'))}</div><div class="row" style="margin-top:7px"><span>Detection / version</span><span class="value ${app.starBreakerDetected===true?'ok':''}">${app.starBreakerDetected===true?htmlEsc(uiT('status.found','FOUND'))+' · '+htmlEsc(app.starBreakerVersion||uiT('status.detected','DETECTED')):htmlEsc(uiT('status.notFoundPath','NOT FOUND · path required'))}</span></div><label style="margin-top:9px">StarBreaker path<input id="wsStarBreakerPath" type="text" placeholder="D:\StarBreaker\starbreaker.exe" value="${htmlEsc(app.starBreakerPath||'')}"></label><label>Data.p4k path<input id="wsDataP4kPath" type="text" placeholder="StarCitizen\LIVE\Data.p4k" value="${htmlEsc(app.dataP4kPath||'')}"></label></details>
  <details class="workspaceSubcard"><summary>SCUnpacked data import</summary><label class="displayRow"><input id="wsScUnpacked" type="checkbox"><span>Enable local SCUnpacked enrichment</span><span class="displayIcon">S</span></label><div class="workspaceNote">${htmlEsc(uiT('note.scInstall','Preferred installation: download/copy the SCUnpacked data folder below StarSyncUniverse/database. StarSyncUniverse searches that directory recursively for starmap_positions.json and uses the containing folder automatically. If no dataset is found, configure its root path below. When enabled, SCUnpacked refreshes readable names, descriptions, factions, services, trade/location semantics and related metadata; it does not replace LIVE geometry or packaged body textures. After a Star Citizen/SCUnpacked update, replace the dataset in /database (or update the configured folder) and use Save & reload data sources so the semantic database is rebuilt from the newer snapshot.'))}</div><div class="row" style="margin-top:7px"><span>Detection / version</span><span class="value ${app.scUnpackedDetected===true?'ok':''}">${app.scUnpackedDetected===true?htmlEsc(uiT('status.found','FOUND'))+' · '+htmlEsc(app.scUnpackedVersion||uiT('status.detected','DETECTED')):htmlEsc(uiT('status.notFoundPath','NOT FOUND · path required'))}</span></div><label style="margin-top:9px">SCUnpacked root<input id="wsScRoot" type="text" placeholder="Auto-discover latest below /Datenbank" value="${htmlEsc(app.scUnpackedRoot||'')}"></label></details>
  <details class="workspaceSubcard"><summary>Online API enrichment</summary><div class="row"><span>Provider</span><span class="value">${htmlEsc(app.onlineProvider||'Star-Citizen.wiki API / starcitizen.tools media')}</span></div><label class="displayRow"><input id="wsOnlineConsent" type="checkbox"><span>I consent to external HTTP requests</span><span class="displayIcon">C</span></label><div class="workspaceNote">${htmlEsc(uiT('note.onlineConsent','Consent is required before any external enrichment request is sent. When enabled, StarSyncUniverse may refresh location descriptions/details and cache available images from the configured external provider. Normal web-request metadata, including the public IP address, can be visible to that provider. The packaged location baseline remains fully usable without this option.'))}</div><label class="displayRow" style="margin-top:8px"><input id="wsOnlineEnrichment" type="checkbox"><span>Enable online location enrichment</span><span class="displayIcon">N</span></label><div id="wsOnlineState" class="workspaceNote"></div><button id="wsClearOnlineCache" style="margin-top:8px">Clear online enrichment cache</button></details>
 </div>
  <div class="workspaceCard"><h4>StarSync Sync Host</h4><div class="workspaceNote">${htmlEsc(uiT('note.syncHost','Configure the complete public SyncHost base URL (scheme, host, port and API base path), then enter the Star Citizen player handle and optional organization. StarSyncUniverse creates a persistent Client ID and ECDSA-P256/SHA-256 identity; the private key remains DPAPI-protected on this Windows account. Probe connection first requests sync/sync-host-manifest.json and then sends a signed request to api/v1/clients/me?clientId=.... A successful probe requires both the manifest and an authorized/known client registry response.'))}</div><label class="displayRow" style="margin-top:8px"><input id="wsSyncHostEnabled" type="checkbox"><span>Enable SyncHost connection</span><span class="displayIcon">S</span></label><label style="margin-top:8px">SyncHost base URL<input id="wsSyncHostBaseUrl" type="text" placeholder="https://host.example:18443/starsync-api/" value="${htmlEsc(app.syncHostBaseUrl||'')}"></label><label>Transport<select id="wsSyncHostTransport"><option value="auto">Auto</option><option value="rest-as2">REST / AS2-Lite</option></select></label><label>Player / handle<input id="wsSyncHostPlayer" type="text" value="${htmlEsc(app.syncHostPlayerHandle||'')}"></label><label>Organization<input id="wsSyncHostOrganization" type="text" value="${htmlEsc(app.syncHostOrganization||'')}"></label><div class="row"><span>Client ID</span><span class="value">${htmlEsc(app.syncHostClientId||'-')}</span></div><div class="row"><span>Fingerprint</span><span class="value" style="font-size:9px">${htmlEsc(app.syncHostClientFingerprint||'-')}</span></div><div class="row"><span>Signature</span><span class="value">${htmlEsc(app.syncHostSignatureAlgorithm||'ECDSA-P256-SHA256')}</span></div><div id="wsSyncHostState" class="workspaceNote" style="margin-top:7px">${htmlEsc(app.syncHostEnabled===true?uiT('status.configuredProbe','CONFIGURED / probe not run'):uiT('settings.off','OFF'))}</div><div style="margin-top:8px"><button id="wsSyncHostSave">Save SyncHost settings</button><button id="wsSyncHostProbe" style="margin-left:6px">Probe connection</button></div></div>
  <div class="workspaceCard"><h4>Renderer</h4><div class="row"><span>WebGL2</span><span class="value">${htmlEsc(glRenderer.available?uiT('status.rendererActive','ACTIVE'):uiT('status.rendererFallback','FALLBACK'))}</span></div><div class="row"><span>Body texture entries</span><span class="value">${surfaceTextures.length}</span></div><div class="workspaceNote" style="margin-top:8px">${htmlEsc(uiT('note.renderer','Body textures are demand-loaded and retained in a bounded GPU/image LRU. Cloud and normal maps remain LOD-lazy.'))}</div></div>
  <div class="workspaceCard"><h4>Camera</h4><label class="displayRow"><input id="wsIllustratedSystem" type="checkbox"><span>Illustrated system overview</span><span class="displayIcon">I</span></label><div class="workspaceNote">${htmlEsc(uiT('note.camera','Presentation-only: moons, stations and local orbit cues remain readable in the zoomed-out system view and blend continuously back to true projected spacing while zooming in.'))}</div><label class="displayRow"><input id="wsSurveyNightFilter" type="checkbox"><span>Survey night-side filter</span><span class="displayIcon">N</span></label><div class="workspaceNote">When Survey Lighting is active, the hemisphere facing away from the star keeps the full surface texture visible under a translucent cyan/teal night-vision filter. Disable this option for neutral full-surface Survey Lighting.</div><label class="displayRow"><input id="wsMapLegend" type="checkbox"><span>Show bottom map legend</span><span class="displayIcon">L</span></label><label class="displayRow"><input id="wsCameraTravelEnabled" type="checkbox"><span>Smooth focus travel</span><span class="displayIcon">T</span></label><label style="margin-top:9px">Focus travel speed<select id="wsCameraTravelDuration"><option value="500">${htmlEsc(uiT('settings.fast','Fast - 0.5 s'))}</option><option value="1000">${htmlEsc(uiT('settings.normal','Normal - 1.0 s'))}</option><option value="1600">${htmlEsc(uiT('settings.slow','Slow - 1.6 s'))}</option><option value="2400">${htmlEsc(uiT('settings.cinematic','Cinematic - 2.4 s'))}</option><option value="3500">${htmlEsc(uiT('settings.verySlow','Very slow - 3.5 s'))}</option></select></label><button id="wsSettingsReset" style="margin-top:8px">Reset camera</button></div>
  <div class="workspaceCard"><h4>Apply data-source settings</h4><div class="workspaceNote">${htmlEsc(uiT('note.applySources','Changing the Data.p4k adapter or SCUnpacked source reloads the universe dataset. Online access remains separately gated by explicit consent.'))}</div><button id="wsSaveSources" style="margin-top:9px">Save & reload data sources</button><div id="wsSaveState" class="workspaceNote" style="margin-top:7px"></div></div>
  <div class="workspaceCard diagnosticsCard"><h4>Integrity & Support</h4><div class="workspaceNote">${htmlEsc(uiT('note.integrity','Runs a read-only validation of the StarSyncUniverse installation, required StarBreaker commands, Data.p4k access, SCUnpacked structure/content and the configured SyncHost connection. The result is written as a log and a ZIP support package. Private SyncHost key material, bookmarks and raw game/database payloads are never included.'))}</div><button id="wsRunDiagnostics" style="margin-top:9px">Run integrity check & create support package</button><div id="wsDiagnosticsState" class="workspaceNote" style="margin-top:7px;overflow-wrap:anywhere">Not run.</div><div id="wsDiagnosticsResults" class="diagnosticsResults" style="margin-top:8px"></div></div>
 </div>`;
 for(const c of workspaceBody.querySelectorAll('[data-setting]'))c.onchange=()=>{const target=document.getElementById(c.dataset.setting);target.checked=c.checked;target.dispatchEvent(new Event('change'))};
 const illustrated=document.getElementById('wsIllustratedSystem'),nightFilterSetting=document.getElementById('wsSurveyNightFilter'),legendSetting=document.getElementById('wsMapLegend'),travelEnabled=document.getElementById('wsCameraTravelEnabled'),travelDuration=document.getElementById('wsCameraTravelDuration');
 illustrated.checked=illustratedSystemEnabled();nightFilterSetting.checked=surveyNightFilterEnabled();legendSetting.checked=mapLegendVisible();travelEnabled.checked=cameraTravelEnabled();travelDuration.value=String(cameraTravelDurationMs());if(![...travelDuration.options].some(o=>o.value===travelDuration.value))travelDuration.value='1600';
 illustrated.onchange=()=>{safePreferenceSet('starsyncUniverse.illustratedSystem',illustrated.checked?'true':'false');invalidateVisible();draw()};nightFilterSetting.onchange=()=>{const target=document.getElementById('surveyNightFilter');target.checked=nightFilterSetting.checked;target.dispatchEvent(new Event('change'))};legendSetting.onchange=()=>{safePreferenceSet('starsyncUniverse.mapLegendVisible',legendSetting.checked?'true':'false');applyMapLegendVisibility()};travelEnabled.onchange=()=>safePreferenceSet('starsyncUniverse.cameraTravelEnabled',travelEnabled.checked?'true':'false');travelDuration.onchange=()=>safePreferenceSet('starsyncUniverse.cameraTravelDurationMs',travelDuration.value);document.getElementById('wsSettingsReset').onclick=()=>document.getElementById('reset').click();
 const p4k=document.getElementById('wsLocalP4k'),sc=document.getElementById('wsScUnpacked'),consent=document.getElementById('wsOnlineConsent'),online=document.getElementById('wsOnlineEnrichment'),onlineState=document.getElementById('wsOnlineState'),syncEnabled=document.getElementById('wsSyncHostEnabled'),syncTransport=document.getElementById('wsSyncHostTransport'),syncState=document.getElementById('wsSyncHostState'),uiLanguageSelect=document.getElementById('wsUiLanguage');
 uiLanguageSelect.value=app.uiLanguage||uiLanguage;
 p4k.checked=app.localP4kUpdateAdapterEnabled===true;sc.checked=app.scUnpackedImportEnabled===true;consent.checked=app.onlineLocationEnrichmentConsent===true;online.checked=app.onlineLocationEnrichmentEnabled===true&&consent.checked;syncEnabled.checked=app.syncHostEnabled===true;syncTransport.value=app.syncHostTransportMode||'auto';if(![...syncTransport.options].some(o=>o.value===syncTransport.value))syncTransport.value='auto';
 const syncOnlineGate=()=>{online.disabled=!consent.checked;if(!consent.checked)online.checked=false;onlineState.textContent=online.checked&&consent.checked?uiT('status.onlineActive','ACTIVE - external requests allowed by user consent'):uiT('status.onlineOff','OFF - no external enrichment requests');onlineState.className='workspaceNote '+(online.checked&&consent.checked?'ok':'muted')};syncOnlineGate();consent.onchange=syncOnlineGate;online.onchange=syncOnlineGate;
 document.getElementById('wsClearOnlineCache').onclick=()=>{if(window.chrome?.webview)window.chrome.webview.postMessage({type:'clearOnlineEnrichmentCache'});onlineState.textContent=uiT('status.cacheClearRequested','Cache clear requested.')};
 const postSettings=(reload)=>{if(window.chrome?.webview)window.chrome.webview.postMessage({type:'applicationSettingsUpdate',localP4kUpdateAdapterEnabled:p4k.checked,scUnpackedImportEnabled:sc.checked,onlineLocationEnrichmentConsent:consent.checked,onlineLocationEnrichmentEnabled:online.checked,starBreakerPath:document.getElementById('wsStarBreakerPath').value,dataP4kPath:document.getElementById('wsDataP4kPath').value,scUnpackedRoot:document.getElementById('wsScRoot').value,syncHostEnabled:syncEnabled.checked,syncHostBaseUrl:document.getElementById('wsSyncHostBaseUrl').value,syncHostTransportMode:syncTransport.value,syncHostPlayerHandle:document.getElementById('wsSyncHostPlayer').value,syncHostOrganization:document.getElementById('wsSyncHostOrganization').value,uiLanguage:uiLanguageSelect.value,reload})};
 uiLanguageSelect.onchange=()=>postSettings(true);
 document.getElementById('wsSyncHostSave').onclick=()=>{postSettings(false);syncState.textContent=uiT('status.settingsSaved','Settings saved locally.')};document.getElementById('wsSyncHostProbe').onclick=()=>{postSettings(false);syncState.textContent=uiT('status.probingSync','Probing signed SyncHost connection...');setTimeout(()=>{if(window.chrome?.webview)window.chrome.webview.postMessage({type:'syncHostProbeRequest'})},80)};
 document.getElementById('wsRunDiagnostics').onclick=()=>{const button=document.getElementById('wsRunDiagnostics'),state=document.getElementById('wsDiagnosticsState'),results=document.getElementById('wsDiagnosticsResults');button.disabled=true;button.textContent=uiT('status.runningIntegrity','Running integrity check...');state.textContent=uiT('status.validatingSupport','Saving current settings and validating Tool / StarBreaker / SCUnpacked / SyncHost...');state.className='workspaceNote';results.innerHTML='';postSettings(false);setTimeout(()=>{if(window.chrome?.webview)window.chrome.webview.postMessage({type:'supportDiagnosticsRequest'})},120)};
 document.getElementById('wsSaveSources').onclick=()=>{const save=document.getElementById('wsSaveSources'),state=document.getElementById('wsSaveState');if(online.checked&&!consent.checked){state.textContent=uiT('status.onlineConsentRequired','Online enrichment requires consent.');return}save.disabled=true;save.textContent=uiT('status.saving','Saving...');state.textContent=uiT('status.savingReload','Saving settings and reloading data sources...');if(window.chrome?.webview)window.chrome.webview.postMessage({type:'applicationSettingsUpdate',localP4kUpdateAdapterEnabled:p4k.checked,scUnpackedImportEnabled:sc.checked,onlineLocationEnrichmentConsent:consent.checked,onlineLocationEnrichmentEnabled:online.checked,starBreakerPath:document.getElementById('wsStarBreakerPath').value,dataP4kPath:document.getElementById('wsDataP4kPath').value,scUnpackedRoot:document.getElementById('wsScRoot').value,reload:true})};
}
function workspaceAbout(){
 const app=data.applicationSettings||{};
 if(uiLanguage!=='de'){
  workspaceTitle.textContent='About';workspaceSubtitle.textContent='Installation · Configuration · Data sources · SyncHost · Support';
  const statusChip=(ok,on,off)=>`<span class="value ${ok?'ok':'warn'}">${ok?on:off}</span>`;
  workspaceBody.innerHTML=`<div style="position:relative;min-height:100%;box-sizing:border-box;padding:24px 24px 250px;background:#000;overflow:hidden"><div style="position:relative;z-index:2;max-width:1040px">
  <div class="workspaceCard" style="background:#06131cf2"><h4>StarSyncUniverse · User Guide</h4><div class="workspaceNote" style="font-size:11px;line-height:1.65;color:#cde8f2">This view is organized as a setup and operating reference. Recommended order for a new installation: <b>1. Basic operation</b> → <b>2. Data sources</b> → <b>3. SyncHost</b> → <b>4. Diagnostics & Support</b>. StarSyncUniverse remains usable without optional external sources through its packaged community baseline.</div></div>
  <div class="workspaceCard" style="margin-top:12px;background:#06131cf2"><h4>1 · Basic operation</h4><div class="workspaceGrid"><div><div class="workspaceNote"><b>Map</b><br>Mouse wheel: zoom to cursor<br>Left drag: pan<br>Middle drag: orbit/tilt<br>Double-click: focus object<br>Right-click: navigation/bookmark</div></div><div><div class="workspaceNote"><b>Views</b><br>SYS: system map, green switch<br>GLX: galaxy topology, blue switch<br>Global search: all loaded systems<br>System selector: change active system</div></div><div><div class="workspaceNote"><b>Navigation</b><br>Set start/destination by right-click<br>Direct Line: compatible coordinate frames<br>Route: known Jump Point connections<br>Bookmarks: objects, surface targets and free positions</div></div></div></div>
  <div class="workspaceCard" style="margin-top:12px;background:#06131cf2"><h4>2 · Configure data sources</h4><div class="workspaceSubcard"><b style="color:#8bdff0">A · StarBreaker / CURRENT LIVE Data.p4k</b><div class="workspaceNote" style="margin-top:6px;line-height:1.6"><b>Installation:</b> copy <code>starbreaker.exe</code> into the StarSyncUniverse application directory or a subdirectory. StarSyncUniverse detects it automatically. If no executable is found, configure the full path in Settings.<br><b>Status:</b> ${statusChip(app.starBreakerDetected===true,'FOUND · '+htmlEsc(app.starBreakerVersion||'DETECTED'),'NOT FOUND · path required')}<br><b>Data.p4k:</b> configure the Star Citizen LIVE <code>Data.p4k</code>. When the adapter is active, StarBreaker reads the current game data and refreshes authoritative placements/objects and local presentation caches.<br><b>After a Star Citizen update:</b> the configured path remains valid and the next reload reads the updated Data.p4k. If the new data format requires a newer StarBreaker version, replace starbreaker.exe and run the Integrity Check.</div></div>
  <div class="workspaceSubcard"><b style="color:#8bdff0">B · SCUnpacked</b><div class="workspaceNote" style="margin-top:6px;line-height:1.6"><b>Installation:</b> copy the unpacked dataset to <code>StarSyncUniverse/database</code>. StarSyncUniverse recursively searches for <code>starmap_positions.json</code> and uses its containing folder as the root. An external root path can be configured instead.<br><b>Status:</b> ${statusChip(app.scUnpackedDetected===true,'FOUND · '+htmlEsc(app.scUnpackedVersion||'DETECTED'),'NOT FOUND · path required')}<br><b>Use:</b> SCUnpacked enriches readable names, descriptions, factions, services, trade/location semantics and related metadata. It never replaces CURRENT LIVE geometry or packaged body textures.<br><b>Update:</b> replace/copy the new snapshot into <code>/database</code>, then use <b>Save & reload data sources</b>. Integrity Check validates required files, JSON structure and a complete semantic load.</div></div>
  <div class="workspaceSubcard"><b style="color:#8bdff0">C · Online Enrichment</b><div class="workspaceNote" style="margin-top:6px;line-height:1.6">External HTTP requests remain disabled without explicit consent. Online Enrichment may cache supplemental descriptions/media, but is never authoritative for geometry or coordinates.</div></div></div>
  <div class="workspaceCard" style="margin-top:12px;background:#06131cf2"><h4>3 · Connect SyncHost</h4><div class="workspaceNote" style="line-height:1.6"><b>Required information:</b><br>1. Enable <b>SyncHost connection</b>.<br>2. Enter the complete public base URL: scheme + host + port + API base path, for example <code>https://host.example:18443/starsync-api/</code>.<br>3. Enter the Star Citizen player/handle; organization is optional.<br>4. Keep transport on <b>Auto</b> unless REST / AS2-Lite is explicitly required.<br>5. Use <b>Save SyncHost settings</b>, then <b>Probe connection</b>.<br><br><b>Probe process:</b> StarSyncUniverse first requests <code>sync/sync-host-manifest.json</code>, then sends a signed request to <code>api/v1/clients/me?clientId=...</code>. The persistent ECDSA-P256/SHA-256 client identity keeps its private key DPAPI-protected for the current Windows user and never exports it to support packages.<br><br><b>Results:</b> <code>VALID/KNOWN</code> = manifest reachable and client authorized; <code>NOT_AUTHORIZED</code> = HTTP 401/403; <code>NOT_REGISTERED</code> = HTTP 404; <code>ERROR</code> = typically URL/TLS/reverse-proxy/transport failure.<br><br><b>Client ID:</b> <code>${htmlEsc(app.syncHostClientId||'-')}</code><br><b>Fingerprint:</b> <code>${htmlEsc(app.syncHostClientFingerprint||'-')}</code></div></div>
  <div class="workspaceCard" style="margin-top:12px;background:#06131cf2"><h4>4 · Integrity Check & Support Package</h4><div class="workspaceNote" style="line-height:1.6">Settings → Integrity & Support runs a read-only validation of StarSyncUniverse core files and baseline JSON, StarBreaker installation/version and required CLI commands (<code>--help</code>, <code>p4k extract --help</code>, <code>dcb query --help</code>), Data.p4k readability, required/enrichment SCUnpacked files and semantic load, plus the configured SyncHost probe. Results are shown directly and written as <code>.log</code> and <code>.zip</code> under <code>%LOCALAPPDATA%\\StarSyncUniverse\\Support</code>. The package never contains private keys, bookmarks, Data.p4k or raw SCUnpacked payloads.</div></div>
  <div class="workspaceGrid" style="margin-top:12px"><div class="workspaceCard" style="background:#06131cf2"><h4>5 · Current data status</h4><div class="row"><span>System</span><span class="value">${htmlEsc(data.system.toUpperCase())}</span></div><div class="row"><span>Entities</span><span class="value">${data.entities.length}</span></div><div class="row"><span>Physical bodies</span><span class="value">${(data.bodies||[]).length}</span></div><div class="row"><span>Body-local targets</span><span class="value">${surfaceTargets.length}</span></div></div><div class="workspaceCard" style="background:#06131cf2"><h4>Data authority</h4><div class="workspaceNote">With the local LIVE adapter enabled, CURRENT LIVE Data.p4k is authoritative for placement/geometry. SCUnpacked and online services are enrichment only. Presentation textures never alter coordinates, routes or canonical identity.</div></div></div>
  <div class="workspaceNote" style="margin-top:14px;color:#546f7c">Unofficial community software. Not affiliated with or endorsed by Cloud Imperium Games or Roberts Space Industries.</div>
  </div><img src="https://starsync-branding/starsyncuniverse_about.jpg" alt="StarSyncUniverse" style="position:absolute;right:18px;bottom:16px;width:min(400px,38vw);max-width:400px;max-height:220px;height:auto;object-fit:contain;object-position:right bottom;border:0;outline:0;box-shadow:none;background:transparent;z-index:1;pointer-events:none"></div>`;
  return;
 }
 workspaceTitle.textContent='About';workspaceSubtitle.textContent='Installation · Configuration · Data sources · SyncHost · Support';
 const statusChip=(ok,on,off)=>`<span class="value ${ok?'ok':'warn'}">${ok?on:off}</span>`;
 workspaceBody.innerHTML=`<div style="position:relative;min-height:100%;box-sizing:border-box;padding:24px 24px 250px;background:#000;overflow:hidden"><div style="position:relative;z-index:2;max-width:1040px">
 <div class="workspaceCard" style="background:#06131cf2"><h4>StarSyncUniverse · Benutzerhandbuch</h4><div class="workspaceNote" style="font-size:11px;line-height:1.65;color:#cde8f2">Diese Ansicht ist als klare Einrichtungs- und Betriebsreferenz aufgebaut. Reihenfolge für eine neue Installation: <b>1. Grundbedienung</b> → <b>2. Datenquellen</b> → <b>3. SyncHost</b> → <b>4. Diagnose & Support</b>. Die Anwendung bleibt auch ohne optionale externe Datenquellen mit der paketierten Community-Baseline nutzbar.</div></div>
 <div class="workspaceCard" style="margin-top:12px;background:#06131cf2"><h4>1 · Grundbedienung</h4><div class="workspaceGrid"><div><div class="workspaceNote"><b>Karte</b><br>Mausrad: Zoom zum Cursor<br>Linke Maustaste ziehen: Pan<br>Mittlere Maustaste ziehen: Orbit/Tilt<br>Doppelklick: Objekt fokussieren<br>Rechtsklick: Navigation/Bookmark</div></div><div><div class="workspaceNote"><b>Ansichten</b><br>SYS: Systemkarte, grüner Schalter<br>GLX: Galaxy-Topologie, blauer Schalter<br>Globale Suche: alle geladenen Systeme<br>Systemselektor: aktives System wechseln</div></div><div><div class="workspaceNote"><b>Navigation</b><br>Start/Ziel per Rechtsklick setzen<br>Direct Line: kompatible Koordinatenrahmen<br>Route: bekannte Jump-Point-Verbindungen<br>Bookmarks: Objekte, Surface Targets und freie Positionen</div></div></div></div>
 <div class="workspaceCard" style="margin-top:12px;background:#06131cf2"><h4>2 · Datenquellen einrichten</h4><div class="workspaceSubcard"><b style="color:#8bdff0">A · StarBreaker / CURRENT LIVE Data.p4k</b><div class="workspaceNote" style="margin-top:6px;line-height:1.6"><b>Installation:</b> <code>starbreaker.exe</code> in das StarSyncUniverse-Programmverzeichnis oder einen Unterordner kopieren. StarSyncUniverse sucht dort automatisch. Wird keine EXE gefunden, in Settings den vollständigen Pfad angeben.<br><b>Status:</b> ${statusChip(app.starBreakerDetected===true,'FOUND · '+htmlEsc(app.starBreakerVersion||'DETECTED'),'NOT FOUND · Pfad erforderlich')}<br><b>Data.p4k:</b> Pfad zur Star-Citizen-LIVE-<code>Data.p4k</code> konfigurieren. Bei aktivem Adapter liest StarBreaker die aktuelle Spieldatei und aktualisiert autoritative Placements/Objekte sowie lokale Präsentations-Caches.<br><b>Nach einem Star-Citizen-Update:</b> Data.p4k bleibt derselbe konfigurierte Zielpfad, wird beim nächsten Reload neu gelesen. Falls das neue Datenformat mit der vorhandenen StarBreaker-Version nicht mehr verarbeitet werden kann, StarBreaker durch eine kompatible neue Version ersetzen und den Integrity Check ausführen.</div></div>
 <div class="workspaceSubcard"><b style="color:#8bdff0">B · SCUnpacked</b><div class="workspaceNote" style="margin-top:6px;line-height:1.6"><b>Installation:</b> entpackten Datensatz nach <code>StarSyncUniverse/database</code> kopieren. StarSyncUniverse sucht rekursiv nach <code>starmap_positions.json</code> und verwendet dessen Ordner als Root. Alternativ kann ein externer Root-Pfad eingetragen werden.<br><b>Status:</b> ${statusChip(app.scUnpackedDetected===true,'FOUND · '+htmlEsc(app.scUnpackedVersion||'DETECTED'),'NOT FOUND · Pfad erforderlich')}<br><b>Verwendung:</b> SCUnpacked ergänzt lesbare Namen, Beschreibungen, Fraktionen, Services, Trade-/Location-Semantik und verwandte Metadaten. Es ersetzt niemals CURRENT-LIVE-Geometrie oder die paketierten Body-Texturen.<br><b>Update:</b> neuen Snapshot in <code>/database</code> ersetzen/kopieren, danach <b>Save & reload data sources</b>. Der Integrity Check validiert Pflichtdateien, JSON-Struktur und einen vollständigen semantischen Ladevorgang.</div></div>
 <div class="workspaceSubcard"><b style="color:#8bdff0">C · Online Enrichment</b><div class="workspaceNote" style="margin-top:6px;line-height:1.6">Externe HTTP-Abfragen bleiben ohne ausdrücklichen Consent deaktiviert. Online Enrichment darf zusätzliche Beschreibungen/Medien cachen, ist aber nie Quelle für autoritative Geometrie oder Koordinaten.</div></div></div>
 <div class="workspaceCard" style="margin-top:12px;background:#06131cf2"><h4>3 · SyncHost anbinden</h4><div class="workspaceNote" style="line-height:1.6"><b>Benötigte Angaben:</b><br>1. <b>Enable SyncHost connection</b> aktivieren.<br>2. Vollständige öffentliche Base-URL eintragen: Schema + Host + Port + API-Basispfad, z. B. <code>https://host.example:18443/starsync-api/</code>.<br>3. Star-Citizen-Player/Handle eintragen; Organization optional.<br>4. Transport normalerweise auf <b>Auto</b> lassen; alternativ REST / AS2-Lite.<br>5. <b>Save SyncHost settings</b> und anschließend <b>Probe connection</b> ausführen.<br><br><b>Was beim Probe passiert:</b> zuerst wird <code>sync/sync-host-manifest.json</code> aufgerufen. Danach folgt ein signierter Request an <code>api/v1/clients/me?clientId=...</code>. StarSyncUniverse verwendet eine persistente ECDSA-P256/SHA-256-Client-Identität; der private Schlüssel bleibt DPAPI-geschützt beim Windows-Benutzer und wird nie in Supportpakete geschrieben.<br><br><b>Auswertung:</b> <code>VALID/KNOWN</code> = Manifest erreichbar und Client registriert/autorisiert. <code>NOT_AUTHORIZED</code> = HTTP 401/403. <code>NOT_REGISTERED</code> = HTTP 404. <code>ERROR</code> = typischerweise URL/TLS/Reverse-Proxy/Transportproblem.<br><br><b>Client ID:</b> <code>${htmlEsc(app.syncHostClientId||'-')}</code><br><b>Fingerprint:</b> <code>${htmlEsc(app.syncHostClientFingerprint||'-')}</code></div></div>
 <div class="workspaceCard" style="margin-top:12px;background:#06131cf2"><h4>4 · Integrity Check & Support Package</h4><div class="workspaceNote" style="line-height:1.6">Unter <b>Settings → Integrity & Support</b> startet ein read-only Gesamttest. Geprüft werden: StarSyncUniverse-Kerndateien und JSON-Baseline, StarBreaker-Installation/Version und die benötigten CLI-Kommandos (<code>--help</code>, <code>p4k extract --help</code>, <code>dcb query --help</code>), Lesbarkeit der Data.p4k, SCUnpacked-Pflicht-/Enrichment-Dateien und semantischer Load-Test sowie der konfigurierte SyncHost-Probe. Ergebnis wird direkt angezeigt und zusätzlich als <code>.log</code> und <code>.zip</code> unter <code>%LOCALAPPDATA%\StarSyncUniverse\Support</code> gespeichert. Das ZIP enthält keine privaten Schlüssel, keine Bookmarks und keine Rohkopie von Data.p4k oder SCUnpacked.</div></div>
 <div class="workspaceGrid" style="margin-top:12px"><div class="workspaceCard" style="background:#06131cf2"><h4>5 · Aktueller Datenstatus</h4><div class="row"><span>System</span><span class="value">${htmlEsc(data.system.toUpperCase())}</span></div><div class="row"><span>Entities</span><span class="value">${data.entities.length}</span></div><div class="row"><span>Physical bodies</span><span class="value">${(data.bodies||[]).length}</span></div><div class="row"><span>Body-local targets</span><span class="value">${surfaceTargets.length}</span></div></div><div class="workspaceCard" style="background:#06131cf2"><h4>Datenautorität</h4><div class="workspaceNote">Bei aktivem Local-LIVE-Adapter ist CURRENT LIVE Data.p4k die Autorität für Placement/Geometrie. SCUnpacked und Online-Dienste sind Enrichment. Präsentationstexturen ändern niemals Koordinaten, Routen oder kanonische Identität.</div></div></div>
 <div class="workspaceNote" style="margin-top:14px;color:#546f7c">Unofficial community software. Not affiliated with or endorsed by Cloud Imperium Games or Roberts Space Industries.</div>
