}function openWorkspace(name){workspacePanel.classList.add('open');if(name==='database')workspaceDatabase();else if(name==='tools')workspaceTools();else if(name==='bookmarks')workspaceBookmarks();else if(name==='settings')workspaceSettings();else workspaceAbout()}
function hashString(s){let h=2166136261>>>0;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}function seeded01(seed){seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return [(seed>>>0)/4294967295,seed>>>0]}
const presentationStars=(()=>{let seed=hashString(String(data.system||'system')+'|starsync-background'),out=[];for(let i=0;i<760;i++){let a;[a,seed]=seeded01(seed);let b;[b,seed]=seeded01(seed);let c;[c,seed]=seeded01(seed);out.push({x:a,y:b,r:.22+c*.95,a:.12+c*.58,w:c>.965})}return out})();
const proceduralAsteroids=(()=>{let out=[];for(const r of (data.regions||[])){if(r.type!=='AsteroidBelt'&&r.type!=='DerivedRingPlacementBand')continue;let seed=hashString(String(r.id||r.name||'ring')+'|asteroids');const count=Math.max(90,Math.min(260,Math.round(140*(Number(r.densityScale)||1))));for(let i=0;i<count;i++){let a;[a,seed]=seeded01(seed);let b;[b,seed]=seeded01(seed);let c;[c,seed]=seeded01(seed);let d;[d,seed]=seeded01(seed);const ang=a*Math.PI*2,ri=Number(r.innerRadiusMeters)||0,ro=Math.max(ri+1,Number(r.outerRadiusMeters)||ri+1),rad=Math.sqrt(ri*ri+b*(ro*ro-ri*ri)),th=(Number(r.thicknessMeters)||0)*(c-.5);out.push({x:(Number(r.centerX)||0)+Math.cos(ang)*rad,y:(Number(r.centerY)||0)+Math.sin(ang)*rad,z:(Number(r.centerZ)||0)+th,size:70+d*430,seed:d*97,kind:'belt'})}}for(const v of (volumes||[])){const t=String(v.type||'');if(!t.includes('AsteroidCluster')&&!t.includes('RingSegment'))continue;let seed=hashString(String(v.id||v.name||'volume')+'|fragments'),count=t.includes('RingSegment')?8:14;for(let i=0;i<count;i++){let a;[a,seed]=seeded01(seed);let b;[b,seed]=seeded01(seed);let c;[c,seed]=seeded01(seed);let d;[d,seed]=seeded01(seed);out.push({x:v.centerX+v.minLocalX+(v.maxLocalX-v.minLocalX)*a,y:v.centerY+v.minLocalY+(v.maxLocalY-v.minLocalY)*b,z:v.centerZ+v.minLocalZ+(v.maxLocalZ-v.minLocalZ)*c,size:(t.includes('RingSegment')?45:90)+d*(t.includes('RingSegment')?260:520),seed:d*131,kind:t.includes('RingSegment')?'nyx':'cluster'})}}return out})();
const asteroidAggregation=(()=>{const out=[],sys=String(data.system||'').toLowerCase();for(const r of (data.regions||[])){if(r.type!=='AsteroidBelt'&&r.type!=='DerivedRingPlacementBand')continue;if(sys==='nyx'&&r.type==='DerivedRingPlacementBand')continue;let seed=hashString(String(r.id||r.name||'belt')+'|aggregation');const count=640;for(let i=0;i<count;i++){let a;[a,seed]=seeded01(seed);let b;[b,seed]=seeded01(seed);let c;[c,seed]=seeded01(seed);let d;[d,seed]=seeded01(seed);const ri=Number(r.innerRadiusMeters)||0,ro=Math.max(ri+1,Number(r.outerRadiusMeters)||ri+1),rad=Math.sqrt(ri*ri+b*(ro*ro-ri*ri)),ang=a*Math.PI*2,th=(Number(r.thicknessMeters)||0)*(c-.5);out.push({x:(Number(r.centerX)||0)+Math.cos(ang)*rad,y:(Number(r.centerY)||0)+Math.sin(ang)*rad,z:(Number(r.centerZ)||0)+th,r:.35+d*1.2,a:.10+d*.26})}}return out})();
const nyxInteriorAsteroids=(()=>{if(String(data.system||'').toLowerCase()!=='nyx')return [];const bg=(volumes||[]).find(v=>String(v.name||'').toLowerCase()==='glaciemring bg')||(volumes||[]).find(v=>String(v.type||'')==='RingSegmentVolume'&&Math.abs(Number(v.centerX)||0)<1&&Math.abs(Number(v.centerY)||0)<1&&Number(v.boundingRadiusMeters)>1e9);if(!bg)return [];const out=[],cx=Number(bg.centerX)||0,cy=Number(bg.centerY)||0,cz=Number(bg.centerZ)||0,outer=Math.max(1,Math.min(Math.max(Math.abs(Number(bg.minLocalX)||0),Math.abs(Number(bg.maxLocalX)||0)),Math.max(Math.abs(Number(bg.minLocalY)||0),Math.abs(Number(bg.maxLocalY)||0)))),inner=outer*.24,thickness=Math.max(1,(Number(bg.maxLocalZ)||0)-(Number(bg.minLocalZ)||0));let seed=hashString(String(bg.id||bg.name||'nyx-glaciem-bg')+'|diffuse-field-v2');for(let i=0;i<3200;i++){let a;[a,seed]=seeded01(seed);let b;[b,seed]=seeded01(seed);let c;[c,seed]=seeded01(seed);let d;[d,seed]=seeded01(seed);let q;[q,seed]=seeded01(seed);const ang=a*Math.PI*2,t=Math.sqrt(b),rad=inner+(outer-inner)*t,n=(rad-inner)/(outer-inner),innerFade=Math.max(0,Math.min(1,n/.18)),outerFade=Math.max(0,Math.min(1,(1-n)/.22)),radialDensity=.28+.72*Math.pow(Math.max(0,Math.min(1,n/.78)),1.15),patch=.64+.18*Math.sin(ang*5.0+n*9.0)+.14*Math.sin(ang*13.0-n*17.0),accept=Math.max(0,Math.min(1,radialDensity*patch));if(q>accept)continue;const edgeFade=Math.pow(innerFade*outerFade,.72),z=(c-.5)*thickness*(.12+.34*n);out.push({x:cx+Math.cos(ang)*rad,y:cy+Math.sin(ang)*rad,z:cz+z,r:.32+d*1.48,a:(.035+d*.24)*edgeFade})}return out})();
function resize(){const r=wrap.getBoundingClientRect();canvas.width=r.width*dpr;canvas.height=r.height*dpr;canvas.style.width=r.width+'px';canvas.style.height=r.height+'px';glCanvas.style.width=r.width+'px';glCanvas.style.height=r.height+'px';glRenderer.resize(r.width,r.height,dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
window.addEventListener('resize',resize);
document.getElementById('toggleLeft').onclick=()=>{root.classList.toggle('leftHidden');setTimeout(resize,170)};
document.getElementById('toggleRight').onclick=()=>{root.classList.toggle('rightHidden');setTimeout(resize,170)};
document.getElementById('tabGlx').onclick=()=>transitionMapMode('galaxy');
document.getElementById('tabSys').onclick=()=>transitionMapMode('system');
document.getElementById('tabObj').onclick=()=>setMapMode('objects');
document.getElementById('galaxyButton').onclick=e=>{e.preventDefault();e.stopPropagation();transitionMapMode(viewMode==='galaxy'?'system':'galaxy')};
for(const section of document.querySelectorAll('aside .section')){section.classList.add('sectionCollapsed');const header=section.querySelector(':scope > h3, :scope > .sectionHeader');if(!header)continue;header.addEventListener('click',ev=>{if(ev.target.closest('button,input,select,textarea'))return;section.classList.toggle('sectionCollapsed');setTimeout(resize,0)})}
function isMajor(e){return ['Star','Planet','Moon','JumpPoint','LagrangePoint','Gateway','Station','BreakerStation','ExtractionStation','LogisticsStation','SecurityStation','ShippingHub','CommArray','LandingZone','NavPoint','Anomaly','AsteroidCluster'].includes(categoryOf(e))||/levski|people/i.test(String(e?.name||''))}
function invalidateVisible(){visibleCache=null}
// The old in-map Search Catalog was removed in favour of the native galaxy-wide search bar.
// Keep the visibility pipeline neutral: object-list filtering must never depend on removed DOM controls.
function catalogFilterActive(){return false}
function catalogFilterMatches(e){return true}
function alwaysOperationallyVisible(e){const c=categoryOf(e);return c==='JumpPoint'||c==='Gateway'||['Station','BreakerStation','ExtractionStation','LogisticsStation','SecurityStation','ShippingHub','CommArray'].includes(c)||/levski|people/i.test(String(e?.name||''))}
function isClusterDetailCategory(c){return c==='Moon'||['Station','BreakerStation','ExtractionStation','LogisticsStation','SecurityStation','ShippingHub','CommArray','LandingZone','NavPoint'].includes(c)}
function activeContextDescendsFrom(ancestor){if(!ancestor?.id)return false;const roots=[selected,focusedTargetId?byId.get(focusedTargetId):null];for(const root of roots){let p=root;for(let i=0;i<16&&p;i++){if(p.id===ancestor.id)return true;p=p.parentId?byId.get(p.parentId):null}}return false}
function clusterDetailVisible(e){const c=categoryOf(e);if(!isClusterDetailCategory(c))return true;if(selected?.id===e.id||focusedTargetId===e.id||hovered?.id===e.id||activeContextDescendsFrom(e))return true;const persistentSystemIcon=['Station','BreakerStation','ExtractionStation','LogisticsStation','SecurityStation','ShippingHub','CommArray'].includes(c)||/levski|people/i.test(String(e?.name||''));if(persistentSystemIcon)return true;const parent=e.parentId?byId.get(e.parentId):null;if(!parent)return c==='Moon'?zoom>=1.05:zoom>=2.5;const pp=project3d(parent.x,parent.y,parent.z),viewportPad=48,parentOnScreen=pp[0]>=-viewportPad&&pp[0]<=projW+viewportPad&&pp[1]>=-viewportPad&&pp[1]<=projH+viewportPad;const physicalDistance=Number(e.distanceToParent)||Math.hypot(e.x-parent.x,e.y-parent.y,e.z-parent.z),apparentSeparation=physicalDistance*projScale;if(c==='Moon')return parentOnScreen&&(illustratedSystemEnabled()||apparentSeparation>=0.8);const closeToCluster=parentOnScreen&&(apparentSeparation>=5.5||zoom>=7);return closeToCluster&&zoom>=1.7}
function visible(){if(visibleCache)return visibleCache;const major=document.getElementById('majorOnly').checked,hidden=document.getElementById('hidden').checked,mapMode=document.getElementById('catalogMapMode').value,filterActive=catalogFilterActive(),showStars=document.getElementById('showStars').checked,showPlanets=document.getElementById('showPlanets').checked,showStations=document.getElementById('showStations').checked,showSystemStations=document.getElementById('showSystemStations').checked,showMissionStations=document.getElementById('showMissionStations').checked,externalOnly=document.getElementById('externalFreightElevatorsOnly').checked,showRacingTracks=document.getElementById('showRacingTracks').checked,showJumpPoints=document.getElementById('showJumpPoints').checked,showAsteroids=document.getElementById('showAsteroids').checked;visibleCache=data.entities.filter(e=>{const c=categoryOf(e),role=stationRole(e),stationLike=role!=='none';if(e.visualClass==='RacingTrack'&&!showRacingTracks)return false;if(stationLike&&externalOnly&&externalFreightElevatorInfo(e)?.isPresent!==true)return false;if(c==='Star'&&!showStars)return false;if((c==='Planet'||c==='Moon')&&!showPlanets)return false;if(stationLike){if(!showStations)return false;if(role==='system'&&!showSystemStations)return false;if(role==='mission'&&!showMissionStations)return false}else if(['LandingZone','NavPoint'].includes(c)&&!showStations)return false;if((c==='JumpPoint'||c==='Gateway')&&!showJumpPoints)return false;if((c==='AsteroidCluster'||c==='AsteroidField')&&!showAsteroids)return false;if(e.type==='Star')return true;if(!hidden&&e.hidden&&!(stationLike&&role==='mission'&&showMissionStations)&&!alwaysOperationallyVisible(e))return false;const match=filterActive&&catalogFilterMatches(e);if(match)return true;if(mapMode==='filter'&&filterActive)return false;if(major&&!isMajor(e))return false;return clusterDetailVisible(e)});return visibleCache}
function updateProjectionState(){projW=wrap.clientWidth;projH=wrap.clientHeight;projCy=Math.cos(cameraYaw);projSy=Math.sin(cameraYaw);projCp=Math.cos(cameraPitch);projSp=Math.sin(cameraPitch);projScale=.44*Math.min(projW,projH)/maxR*zoom}
function project3d(x,y,z){const dx=x-focusX,dy=y-focusY,dz=z-focusZ;const x1=dx*projCy-dy*projSy,y1=dx*projSy+dy*projCy;const y2=y1*projCp-dz*projSp,depth=y1*projSp+dz*projCp;return [projW/2+panX+x1*projScale,projH/2+panY-y2*projScale,projScale,depth]}
function illustratedSystemEnabled(){return safePreferenceGet('starsyncUniverse.illustratedSystem')!=='false'}
function illustratedBlend(){if(viewMode!=='system'||!illustratedSystemEnabled())return 0;return Math.max(0,Math.min(1,(3.8-zoom)/2.8))}
function displayPointForEntity(e){const actual=project3d(e.x,e.y,e.z),blend=illustratedBlend(),c=categoryOf(e);if(blend<=0||!e.parentId||!['Moon','Station','BreakerStation','ExtractionStation','LogisticsStation','SecurityStation','ShippingHub','CommArray'].includes(c))return actual;const parent=byId.get(e.parentId);if(!parent)return actual;const pc=categoryOf(parent);if(c!=='Moon'&&pc!=='Planet'&&pc!=='Moon')return actual;const pp=project3d(parent.x,parent.y,parent.z),dx=actual[0]-pp[0],dy=actual[1]-pp[1],len=Math.hypot(dx,dy);let ux,uy;if(len>.001){ux=dx/len;uy=dy/len}else{const a=(hashString(String(e.id))%6283)/1000;ux=Math.cos(a);uy=Math.sin(a)}const desired=c==='Moon'?34+((hashString(String(e.id))>>>5)%18):22+((hashString(String(e.id))>>>7)%13),ix=pp[0]+ux*desired,iy=pp[1]+uy*desired;return [actual[0]+(ix-actual[0])*blend,actual[1]+(iy-actual[1])*blend,actual[2],actual[3]]}
function worldToScreen(x,y,z=0){return project3d(x,y,z)}
function screenToFocusPlane(sx,sy){const x1=(sx-projW/2-panX)/projScale,y2=-(sy-projH/2-panY)/projScale,depth=0,y1=y2*projCp+depth*projSp,dz=-y2*projSp+depth*projCp,dx=x1*projCy+y1*projSy,dy=-x1*projSy+y1*projCy;return {x:focusX+dx,y:focusY+dy,z:focusZ+dz}}
function placementBookmarkScope(e){if(!e)return 'SPACE';let p=e;for(let i=0;i<12&&p;i++){const c=categoryOf(p);if(i>0&&(c==='Planet'||c==='Moon'))return 'ORBIT';p=p.parentId?byId.get(p.parentId):null}return 'SPACE'}
function surfacePointAtScreen(sx,sy){const overlay=activeBodySurfaceOverlay();if(!overlay||!overlay.visible||overlay.radiusPx<=0)return null;const x1=(sx-overlay.center[0])/overlay.radiusPx,y2=-(sy-overlay.center[1])/overlay.radiusPx,q=x1*x1+y2*y2;if(q>1)return null;const depth=Math.sqrt(Math.max(0,1-q)),y1=y2*projCp+depth*projSp,nz=-y2*projSp+depth*projCp,nx=x1*projCy+y1*projSy,ny=-x1*projSy+y1*projCy,r=overlay.body.RadiusMeters,x=nx*r,y=ny*r,z=nz*r,lat=Math.asin(Math.max(-1,Math.min(1,nz)))*180/Math.PI,lon=Math.atan2(ny,nx)*180/Math.PI;return {kind:'BODY_FIXED_XYZ',scope:'SURFACE',system:data.system,bodyName:overlay.coverage.bodyName,bodySourceUuid:overlay.coverage.sourceUuid||overlay.body.SourceUuid||null,x,y,z,lat,lon,alt:0,label:'Surface cursor',source:'BODY_DISC_FRONT_HEMISPHERE'}}
function surfaceAnchorCandidate(t){const scope=(t.AnchorScope||'').includes('ORBITAL')?'ORBIT':'SURFACE',coverage=surfaceBodyByName.get((t.BodyName||'').toLowerCase());return {kind:'BODY_FIXED_XYZ',scope,system:t.System||data.system,bodyName:t.BodyName,bodySourceUuid:coverage?.sourceUuid||null,x:t.BodyLocalX,y:t.BodyLocalY,z:t.BodyLocalZ,lat:t.AxisLatitudeDegrees,lon:t.AxisLongitudeDegrees,alt:t.AltitudeMeters,label:readableSurfaceName(t),surfaceAnchorId:t.AnchorId,source:'SURFACE_ANCHOR'}}
