function fmt(v){v=Number(v);if(!Number.isFinite(v))return '—';const a=Math.abs(v);if(a>=1e9)return (v/1e9).toFixed(3)+' Gm';if(a>=1e6)return (v/1e6).toFixed(3)+' Mm';if(a>=1e3)return (v/1e3).toFixed(3)+' km';return v.toFixed(2)+' m'}
